insert into public.courses (id, slug, title_en, title_es, description_en, description_es, sort, is_specialty, price_cents) values ('25ce5b98-1483-570a-bfdb-ef5341e52d9f', 'welcome', 'Welcome to Real Care Training!', '¡Bienvenido a Real Care Training!', 'Start here: how training works, what is required each year, and where to get help.', 'Empiece aquí: cómo funciona la capacitación, qué se requiere cada año y dónde pedir ayuda.', 0, false, 1000);
insert into public.lessons (id, course_id, sort, kind, title_en, title_es, body_en, body_es) values ('577667a7-a477-5feb-9ab7-211dbb00b692', '25ce5b98-1483-570a-bfdb-ef5341e52d9f', 0, 'reading', 'How your training works', 'Cómo funciona su capacitación', '## Your training, in one place
Every required course lives in this portal. Your dashboard shows what is due, what you have finished, and your due date.
## Your training cycle
- Required courses renew once a year on your own due date.
- When a new cycle opens, your courses appear again automatically. You do not need to re-enroll.
- Your past completions stay on your record and transcript.
## Getting help
If you are stuck, send a message to Real Care staff from the Messages tab.', '## Su capacitación, en un solo lugar
Todos los cursos requeridos están en este portal. Su panel muestra lo que debe completar, lo que ya terminó y su fecha límite.
## Su ciclo de capacitación
- Los cursos requeridos se renuevan una vez al año en su propia fecha límite.
- Cuando se abre un nuevo ciclo, sus cursos aparecen de nuevo automáticamente. No necesita inscribirse otra vez.
- Sus cursos completados anteriormente se quedan en su historial y en su certificado de estudios.
## Cómo obtener ayuda
Si tiene dudas, envíe un mensaje al personal de Real Care desde la pestaña Mensajes.');
insert into public.lessons (id, course_id, sort, kind, title_en, title_es, body_en, body_es, video_url, video_seconds, video_source) values ('2ee4d7f3-81c2-541c-971a-530235f13630', '25ce5b98-1483-570a-bfdb-ef5341e52d9f', 1, 'video', 'A quick tour of your portal', 'Un recorrido rápido por su portal', 'A short tour of the portal: your dashboard, training, forms and messages. Watch to the end to complete this lesson.', 'Un recorrido corto por el portal: su panel, capacitación, formularios y mensajes. Véalo hasta el final para completar esta lección.', '/media/portal-tour.mp4', 40, 'file');
insert into public.lessons (id, course_id, sort, kind, title_en, title_es, pass_percent) values ('bc7f7817-6718-5be3-8a37-bd9ff34bd29f', '25ce5b98-1483-570a-bfdb-ef5341e52d9f', 2, 'quiz', 'Check your understanding', 'Compruebe lo que aprendió', 80);
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('bc7f7817-6718-5be3-8a37-bd9ff34bd29f', 0, 'When do your required courses renew?', '¿Cuándo se renuevan sus cursos requeridos?', '["Every month", "Once a year on your due date", "Only when staff email you"]'::jsonb, '["Cada mes", "Una vez al año en su fecha límite", "Solo cuando el personal le envía un correo"]'::jsonb, 2, 'Required training renews once a year on your own due date.', 'La capacitación requerida se renueva una vez al año en su propia fecha límite.');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('bc7f7817-6718-5be3-8a37-bd9ff34bd29f', 1, 'What happens to last year''s completions?', '¿Qué pasa con los cursos que completó el año pasado?', '["They are deleted", "They stay on your record and transcript", "You must print them"]'::jsonb, '["Se borran", "Se quedan en su historial y certificado de estudios", "Debe imprimirlos"]'::jsonb, 2, 'History is never deleted. Each year is kept as its own cycle.', 'El historial nunca se borra. Cada año se guarda como su propio ciclo.');
