insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('3c25a1eb-4b5e-5174-b79d-d101d1545f72', 0, 'You suspect abuse. What do you do?', 'Sospecha que hay abuso. ¿Qué hace?', '["Report it right away as trained", "Wait to be sure", "Ask the person to keep it quiet"]'::jsonb, '["Reportarlo de inmediato como se le enseñó", "Esperar a estar seguro", "Pedirle a la persona que no diga nada"]'::jsonb, 1, 'This reflects the course''s main idea.', 'Esto refleja la idea principal del curso.');
