insert into public.courses (id, slug, title_en, title_es, description_en, description_es, sort, is_specialty, price_cents) values ('d7e6c3be-049b-5e0d-ac2c-2090a8c0db53', 'individual-rights', 'Individual Rights', 'Derechos individuales', 'The rights every person receiving services keeps, and how your daily support protects them.', 'Los derechos que conserva toda persona que recibe servicios, y cómo su apoyo diario los protege.', 7, false, 1000);
insert into public.lessons (id, course_id, sort, kind, title_en, title_es, body_en, body_es) values ('345d0137-b8a7-52f3-96c9-88330e2b4e50', 'd7e6c3be-049b-5e0d-ac2c-2090a8c0db53', 0, 'reading', 'Rights every person keeps', 'Derechos que toda persona conserva', '## The same rights as everyone
People with intellectual and developmental disabilities have the same rights as any other person. Receiving services does not take those rights away.
## Examples of everyday rights
- Privacy in their room, mail and phone calls
- Choosing their own clothes, food, friends and activities
- Managing their own money, with support if they want it
- Practicing their religion, or none
- Saying no, and being heard
## Rights can only be limited through a proper process
A right may only be limited when the person''s team follows the required review process and documents it. Never limit a right on your own.', '## Los mismos derechos que todos
Las personas con discapacidades intelectuales y del desarrollo tienen los mismos derechos que cualquier otra persona. Recibir servicios no les quita esos derechos.
## Ejemplos de derechos de todos los días
- Privacidad en su cuarto, su correo y sus llamadas
- Elegir su ropa, comida, amistades y actividades
- Administrar su propio dinero, con apoyo si lo desea
- Practicar su religión, o ninguna
- Decir que no, y ser escuchada
## Los derechos solo se pueden limitar con el proceso adecuado
Un derecho solo se puede limitar cuando el equipo de la persona sigue el proceso de revisión requerido y lo documenta. Nunca limite un derecho por su cuenta.');
insert into public.lessons (id, course_id, sort, kind, title_en, title_es, pass_percent) values ('93aa7cde-7c26-536f-8ab6-8241f105a4a4', 'd7e6c3be-049b-5e0d-ac2c-2090a8c0db53', 1, 'quiz', 'Individual rights quiz', 'Prueba de derechos individuales', 80);
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('93aa7cde-7c26-536f-8ab6-8241f105a4a4', 0, 'Does receiving services take away a person''s rights?', '¿Recibir servicios le quita sus derechos a una persona?', '["Yes", "No", "Only some of them"]'::jsonb, '["Sí", "No", "Solo algunos"]'::jsonb, 2, 'People keep the same rights as everyone else.', 'Las personas conservan los mismos derechos que todos los demás.');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('93aa7cde-7c26-536f-8ab6-8241f105a4a4', 1, 'Who may decide to limit a person''s right?', '¿Quién puede decidir limitar un derecho de una persona?', '["Any caregiver who thinks it is safer", "The person''s team, through the required review process", "A family friend"]'::jsonb, '["Cualquier cuidador que crea que es más seguro", "El equipo de la persona, mediante el proceso de revisión requerido", "Un amigo de la familia"]'::jsonb, 2, 'Limits require the team''s documented review process.', 'Las limitaciones requieren el proceso de revisión documentado del equipo.');
