insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('e6d79768-8547-5334-9f15-2f1d3153863a', 0, 'A person prefers services in Spanish. What should happen?', 'Una persona prefiere recibir servicios en español. ¿Qué debe pasar?', '["Support is offered in Spanish", "They must use English", "Nothing"]'::jsonb, '["Se ofrece apoyo en español", "Debe usar inglés", "Nada"]'::jsonb, 1, 'This reflects the course''s main idea.', 'Esto refleja la idea principal del curso.');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('e6d79768-8547-5334-9f15-2f1d3153863a', 1, 'Where do you go if you have a question about this course?', '¿A dónde acude si tiene una pregunta sobre este curso?', '["Send a message to Real Care staff in the portal", "Post it on social media", "Skip the course"]'::jsonb, '["Enviar un mensaje al personal de Real Care en el portal", "Publicarla en redes sociales", "Saltarse el curso"]'::jsonb, 1, 'Staff answer questions through Messages.', 'El personal responde preguntas por Mensajes.');
insert into public.courses (id, slug, title_en, title_es, description_en, description_es, sort, is_specialty, price_cents) values ('c005138d-d318-56d3-8bc4-415fb3e9fd69', 'confidentiality', 'Confidentiality', 'Confidencialidad', 'Protecting the private information of the people you support: what counts, who may see it, and how to share it safely.', 'Cómo proteger la información privada de las personas que apoya: qué incluye, quién puede verla y cómo compartirla de forma segura.', 11, false, 1000);
insert into public.lessons (id, course_id, sort, kind, title_en, title_es, body_en, body_es) values ('f0fb3688-7c23-5209-affd-87091827a34f', 'c005138d-d318-56d3-8bc4-415fb3e9fd69', 0, 'reading', 'What is protected information?', '¿Qué es la información protegida?', '## Why confidentiality matters
The people you support trust you with details about their health, their family, and their daily life. Keeping that information private protects their dignity and is required by law, including HIPAA.
## What counts as protected information
- Names, addresses, phone numbers and dates of birth
- Medical conditions, medications and appointments
- Behavior notes, incident reports and service plans
- Photos or videos that show the person
## The minimum necessary rule
Share only what someone needs to do their part of the person''s care, and nothing more.', '## Por qué importa la confidencialidad
Las personas que usted apoya le confían datos sobre su salud, su familia y su vida diaria. Mantener esa información privada protege su dignidad y es un requisito de ley, incluida la ley HIPAA.
## Qué se considera información protegida
- Nombres, direcciones, números de teléfono y fechas de nacimiento
- Condiciones médicas, medicamentos y citas
- Notas de comportamiento, informes de incidentes y planes de servicio
- Fotos o videos donde aparezca la persona
## La regla del mínimo necesario
Comparta solo lo que alguien necesita para hacer su parte del cuidado de la persona, y nada más.');
insert into public.lessons (id, course_id, sort, kind, title_en, title_es, body_en, body_es) values ('c29369d4-b21a-5807-a151-381d862c4698', 'c005138d-d318-56d3-8bc4-415fb3e9fd69', 1, 'reading', 'Sharing information safely', 'Cómo compartir información de forma segura', '## Do
- Submit notes and reports through this portal, not by text message or personal email
- Talk about the person in private, where others cannot overhear
- Lock your phone and log out of the portal on shared devices
## Do not
- Post photos or stories about the person on social media
- Leave paperwork in your car or in a shared space
- Share details with friends or family who are not part of the care team
## If something goes wrong
If information is shared by mistake, tell Real Care staff right away. Reporting quickly helps protect the person.', '## Sí haga
- Envíe notas e informes por este portal, no por mensaje de texto ni correo personal
- Hable de la persona en privado, donde otros no puedan escuchar
- Bloquee su teléfono y cierre sesión del portal en dispositivos compartidos
## No haga
- Publicar fotos o historias sobre la persona en redes sociales
- Dejar papeles en su auto o en un espacio compartido
- Compartir detalles con amigos o familiares que no forman parte del equipo de cuidado
## Si algo sale mal
Si se comparte información por error, avise al personal de Real Care de inmediato. Reportar rápido ayuda a proteger a la persona.');
insert into public.lessons (id, course_id, sort, kind, title_en, title_es, pass_percent) values ('c57873c9-d18f-5513-b9ff-8a0db550126b', 'c005138d-d318-56d3-8bc4-415fb3e9fd69', 2, 'quiz', 'Confidentiality quiz', 'Prueba de confidencialidad', 80);
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('c57873c9-d18f-5513-b9ff-8a0db550126b', 0, 'Which of these is protected information?', '¿Cuál de estos es información protegida?', '["The person''s medication list", "The weather today", "Real Care''s office address"]'::jsonb, '["La lista de medicamentos de la persona", "El clima de hoy", "La dirección de la oficina de Real Care"]'::jsonb, 1, 'Health details like medications are protected information.', 'Los datos de salud, como los medicamentos, son información protegida.');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('c57873c9-d18f-5513-b9ff-8a0db550126b', 1, 'What is the best way to send a log note to Real Care?', '¿Cuál es la mejor manera de enviar una nota de registro a Real Care?', '["Text a photo of it", "Submit it in the portal", "Email it from your personal account"]'::jsonb, '["Enviar una foto por mensaje de texto", "Enviarla por el portal", "Enviarla desde su correo personal"]'::jsonb, 2, 'The portal keeps the information secure and on the person''s record.', 'El portal mantiene la información segura y en el expediente de la persona.');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('c57873c9-d18f-5513-b9ff-8a0db550126b', 2, 'You shared a detail by mistake. What should you do?', 'Compartió un dato por error. ¿Qué debe hacer?', '["Nothing, it was an accident", "Tell Real Care staff right away", "Wait until your next training"]'::jsonb, '["Nada, fue un accidente", "Avisar al personal de Real Care de inmediato", "Esperar a su próxima capacitación"]'::jsonb, 2, 'Reporting quickly lets staff take steps to protect the person.', 'Reportar rápido permite que el personal tome medidas para proteger a la persona.');
