insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('c0b7d8c3-4da1-51a5-9f13-cd24e1ffd2be', 0, 'Which of the following is NOT one of the six required parts of a medication order?', 'Which of the following is NOT one of the six required parts of a medication order?', '["Client''s first and last name", "Medication name", "Client''s insurance information", "Physician/provider signature"]'::jsonb, '["Client''s first and last name", "Medication name", "Client''s insurance information", "Physician/provider signature"]'::jsonb, 3, 'A medication order requires the client''s name, medication, dose, route, date, and physician/provider signature. Insurance information is not a required part of the order.', 'A medication order requires the client''s name, medication, dose, route, date, and physician/provider signature. Insurance information is not a required part of the order.');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('c0b7d8c3-4da1-51a5-9f13-cd24e1ffd2be', 1, 'A medication "dose" has three parts. Which of the following correctly identifies those three parts?', 'A medication "dose" has three parts. Which of the following correctly identifies those three parts?', '["Size, frequency, and duration", "Strength, route, and time", "Medication, dose, and route", "Tablets, milligrams, and milliliters"]'::jsonb, '["Size, frequency, and duration", "Strength, route, and time", "Medication, dose, and route", "Tablets, milligrams, and milliliters"]'::jsonb, 1, 'A dose has three parts: size (the amount given at one time), frequency (how often it''s given), and duration (how long it''s taken).', 'A dose has three parts: size (the amount given at one time), frequency (how often it''s given), and duration (how long it''s taken).');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('c0b7d8c3-4da1-51a5-9f13-cd24e1ffd2be', 2, 'Which of the following measurement equivalents is correct?', 'Which of the following measurement equivalents is correct?', '["1 teaspoon = 15 mL", "1 tablespoon = 5 mL", "2 tablespoons = 30 mL = 1 ounce", "1 cc = 5 mL"]'::jsonb, '["1 teaspoon = 15 mL", "1 tablespoon = 5 mL", "2 tablespoons = 30 mL = 1 ounce", "1 cc = 5 mL"]'::jsonb, 3, '2 tablespoons = 30 mL = 1 ounce. (1 tsp = 5 mL; 1 Tbsp = 15 mL = ½ oz; 1 cc = 1 mL.)', '2 tablespoons = 30 mL = 1 ounce. (1 tsp = 5 mL; 1 Tbsp = 15 mL = ½ oz; 1 cc = 1 mL.)');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('c0b7d8c3-4da1-51a5-9f13-cd24e1ffd2be', 3, 'As a QMAP, which type of medication order are you allowed to accept?', 'As a QMAP, which type of medication order are you allowed to accept?', '["A verbal order given by a physician over the phone", "A written physician''s order", "A faxed order from a pharmacist that is not a copy of a signed physician order", "A verbal \"resume previous orders\" instruction after a hospital discharge"]'::jsonb, '["A verbal order given by a physician over the phone", "A written physician''s order", "A faxed order from a pharmacist that is not a copy of a signed physician order", "A verbal \"resume previous orders\" instruction after a hospital discharge"]'::jsonb, 2, 'QMAPs may only act on a written physician''s order. Verbal/phone orders are not accepted, faxes from a pharmacist are not accepted unless they''re a copy of a signed physician order, and "resume previous orders" is not acceptable after a hospital stay.', 'QMAPs may only act on a written physician''s order. Verbal/phone orders are not accepted, faxes from a pharmacist are not accepted unless they''re a copy of a signed physician order, and "resume previous orders" is not acceptable after a hospital stay.');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('c0b7d8c3-4da1-51a5-9f13-cd24e1ffd2be', 4, 'What does the medical abbreviation "prn" mean?', 'What does the medical abbreviation "prn" mean?', '["By mouth", "As needed", "At bedtime", "Three times a day"]'::jsonb, '["By mouth", "As needed", "At bedtime", "Three times a day"]'::jsonb, 2, '"prn" means as needed.', '"prn" means as needed.');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('c0b7d8c3-4da1-51a5-9f13-cd24e1ffd2be', 5, 'What should you do if you make a documentation error on the MAR?', 'What should you do if you make a documentation error on the MAR?', '["Use white-out to cover the mistake and write the correct entry", "Erase the mistake and write the correct entry in pencil", "Draw a single line through the mistake, initial and date it, and explain on the back of the MAR", "Throw away the MAR and start a new one"]'::jsonb, '["Use white-out to cover the mistake and write the correct entry", "Erase the mistake and write the correct entry in pencil", "Draw a single line through the mistake, initial and date it, and explain on the back of the MAR", "Throw away the MAR and start a new one"]'::jsonb, 3, 'Draw a single line through the mistaken entry, initial and date it, and explain on the back of the MAR. Never use white-out, pencil, or attempt to erase.', 'Draw a single line through the mistaken entry, initial and date it, and explain on the back of the MAR. Never use white-out, pencil, or attempt to erase.');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('c0b7d8c3-4da1-51a5-9f13-cd24e1ffd2be', 6, 'When should you document medication administration on the MAR?', 'When should you document medication administration on the MAR?', '["Before administering the medication, so you don''t forget", "Immediately after giving or monitoring the medication", "At the end of your shift, all at once", "The following day during a quiet moment"]'::jsonb, '["Before administering the medication, so you don''t forget", "Immediately after giving or monitoring the medication", "At the end of your shift, all at once", "The following day during a quiet moment"]'::jsonb, 2, 'Always document immediately after giving or monitoring a medication, never before.', 'Always document immediately after giving or monitoring a medication, never before.');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('c0b7d8c3-4da1-51a5-9f13-cd24e1ffd2be', 7, 'How should you document a PRN medication that was administered?', 'How should you document a PRN medication that was administered?', '["Just initial the box; no further documentation is needed", "Initial the appropriate box and document the time, dose, and reason on the reverse side of the MAR", "Document only on the back of the MAR, with no entry in the date box", "Wait 24 hours, then document"]'::jsonb, '["Just initial the box; no further documentation is needed", "Initial the appropriate box and document the time, dose, and reason on the reverse side of the MAR", "Document only on the back of the MAR, with no entry in the date box", "Wait 24 hours, then document"]'::jsonb, 2, 'Initial the appropriate box on the MAR and document the time, dose, and reason why the PRN was administered on the reverse side (or other designated area) of the MAR. Then follow up within 30–60 minutes and document the client''s status.', 'Initial the appropriate box on the MAR and document the time, dose, and reason why the PRN was administered on the reverse side (or other designated area) of the MAR. Then follow up within 30–60 minutes and document the client''s status.');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('c0b7d8c3-4da1-51a5-9f13-cd24e1ffd2be', 8, 'Which of the following should NOT be placed in a Medication Reminder Box (MRB)?', 'Which of the following should NOT be placed in a Medication Reminder Box (MRB)?', '["A routinely scheduled tablet", "A routinely scheduled capsule", "A controlled substance", "A daily multivitamin tablet"]'::jsonb, '["A routinely scheduled tablet", "A routinely scheduled capsule", "A controlled substance", "A daily multivitamin tablet"]'::jsonb, 3, 'Controlled substances cannot be placed in an MRB. Other items that cannot go in an MRB include PRN medications, liquid medications, powders, inhalers, ointments and creams, and medications with special instructions.', 'Controlled substances cannot be placed in an MRB. Other items that cannot go in an MRB include PRN medications, liquid medications, powders, inhalers, ointments and creams, and medications with special instructions.');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('c0b7d8c3-4da1-51a5-9f13-cd24e1ffd2be', 9, 'Before filling an MRB, you must cross-check the MRB label against which of the following?', 'Before filling an MRB, you must cross-check the MRB label against which of the following?', '["Only the medication bottle", "Only the MAR", "Only the physician''s order", "The physician''s order, the MAR, AND the pharmacist-prepared medication bottle"]'::jsonb, '["Only the medication bottle", "Only the MAR", "Only the physician''s order", "The physician''s order, the MAR, AND the pharmacist-prepared medication bottle"]'::jsonb, 4, 'The MRB label must be cross-checked against all three: the physician''s order, the MAR, and the pharmacist-prepared medication bottle. Any discrepancy must be resolved before filling.', 'The MRB label must be cross-checked against all three: the physician''s order, the MAR, and the pharmacist-prepared medication bottle. Any discrepancy must be resolved before filling.');
insert into public.lessons (id, course_id, sort, kind, title_en, title_es, body_en, body_es, video_url, video_seconds, video_source) values ('7efb9730-9c70-50cd-bcbd-e7d7f97917d5', 'bfaf8f11-e6db-5d53-92a6-a1237b0ed30c', 4, 'video', 'Part 3: Units 6, 7 and 8 video', 'Parte 3: Unidades 6, 7 y 8: video', 'Welcome to Real Care! This is Part 3 of your QMAP training, covering Units 6, 7, and 8. In this training, you''ll review the procedures for safely administering medications, what to do when medication errors happen, and how to properly store medications. Let''s get started.

We''ll begin with Unit 6, the medication administration procedure.

Before you do anything else, recall the Seven Rights of medication administration: the right client, the right time, the right medicine, the right dose, the right route, documentation, and the right to refuse. The right time means within thirty minutes before or thirty minutes after the scheduled dose if a specific time is listed on the doctor''s order. For non-time-specific medications, your facility may use "am" or "pm" time slots on the MAR, as long as that''s spelled out in the policies and procedures.

Standard precautions, originally called universal precautions, apply to every client at every contact. You assume every client could be infected, and you protect yourself and the client through proper hygiene. Hand washing is the single most important measure to prevent contamination and the spread of infection. Wash your hands or use sanitizer before any physical contact with a client or with their medications. Wear gloves whenever you''re in direct contact with body fluids, broken skin, mucous membranes, or with medications that touch the skin. When you remove your gloves, turn them inside out as you take them off, and dispose of contaminated gloves in knotted plastic bags to protect janitorial staff.

Before administering, gather the client''s medication and make sure it hasn''t expired, and that every container is labeled with the recipient''s full name. Pull the MAR and the physician''s order. Cross-check the label against the MAR and physician''s order three times — once when you take the medication off the shelf, once when you pour it, and once when you return it to storage. Gather the equipment you''ll need depending on the route: medicine cups, tweezers, and a pill cutter for oral pills; gloves and cotton balls or tissues for drops and ointments; gloves, a medicine cup, and lubricant for suppositories. Take everything to the client or have them come to your administration area, and make sure the space is clean and private.

Always identify the client. You can ask their name and verify with a photograph, or ask a staff member to confirm. Never use another client to identify someone. Then explain the procedure to gain their cooperation, especially with individuals who have cognitive impairments, dementia, or behavioral needs. Use person-centered skills.

Different routes have different procedures. For oral tablets and capsules, the client should be sitting up or standing, not lying down. Offer one tablet at a time with a drink before and after. You may not crush or open any medication, or hide it in food, without a physician''s order. Stay with the client until you''ve confirmed the medication is swallowed. For sublingual tablets, instruct the client to place the tablet under the tongue and not swallow until it''s fully dissolved. With nitroglycerin SL, sit the client down — do not have them lie down — at the first sign of chest pain, administer the tablet, and notify your supervisor immediately. Record the exact minute on the MAR. If chest pain isn''t relieved after one dose, call 911. Tightly recap the nitro bottle, and replace the supply every six months.

For oral liquids, shake suspensions if directed, pour at eye level on a flat surface, and clean the lip of the bottle before recapping. For ointments, lotions, liniments, and aerosols, always wear gloves — never apply with bare fingers. Use a tongue blade as an applicator if helpful. For transdermal patches, remove the old patch, wash both the old and new sites with soap and water, rotate sites to avoid irritation, and write your initials, date, and time on the patch after applying.

For eye drops, cleanse the eye from the inside corner to the outside, retract the lower lid to make a pocket, and instill the drop without touching the eye. Wait three to five minutes between drops if multiple eye medications are ordered. For ear drops, position the client with the affected ear up, instill the drops without touching the dropper to the ear, and place a small wad of cotton in the canal — but return within ten minutes to remove it. For nose drops and nasal spray, avoid touching the applicator to the nose. For inhalers, have the client exhale, then breathe in deeply as you administer the medication, and have them hold their breath as long as possible. Have them rinse their mouth afterward to prevent thrush.

For rectal suppositories, have the client lie on their left side, lubricate the suppository, and insert it about three inches — past the internal sphincter so it isn''t expelled. For vaginal suppositories or creams, position the client on her back in a frog-leg position or on her side, and instruct her to remain lying down for fifteen to thirty minutes for absorption. These are best given at bedtime.

After administration, dispose of used cups and gloves, wash your hands or sanitize before moving to the next client, and document immediately on the MAR. For PRN medications, document the client''s request, the reason, and the follow-up results. Return medication containers to storage. If medication has been removed from its original container, don''t return it — destroy it according to Real Care policy.

That brings us to Unit 7, Medication Errors. A medication error is any administration that goes against a physician''s order and either causes or has the potential to cause harm. Examples include failing to follow the Seven Rights, improper documentation, running out of medication, or giving the wrong medication to the wrong client. If an error happens, immediately document the details on the MAR, notify Real Care and the physician, and follow Real Care''s policy for medication errors. If you give the wrong client the wrong medication, initial the appropriate date box, circle your initials, document the exact reason on the reverse side of the MAR, and contact Real Care.

Finally, Unit 8 covers medication storage. Medications must be stored in a way that ensures the client''s safety, typically in a locked central location that clients cannot access. Refrigerated medications must be stored separately to prevent intermingling. Controlled substances require a double-lock and a two-person count, signed by both staff at the end of each day, or any time the medication leaves and returns to the facility. Any discrepancy must be reported immediately to your supervisor for investigation of possible drug diversion. Medications should never be stored with disinfectants, insecticides, bleaches, household cleaners, or poisons. And remember the difference between the expiration date — printed on the container, or one year after fill if there''s no date — and the refill through date, which is variable and determined by the prescribing authority.

That completes Part 3 of your QMAP training. Please proceed to your test.', '*La versión en español de esta lección está en preparación. Por ahora se muestra en inglés.*

