insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('4dea7348-cf96-5b28-b280-39e79ff5e88d', 0, 'According to the Seven Rights of medication administration, the "right time" means administering medication within what window of the scheduled time stated in the doctor''s order?', 'According to the Seven Rights of medication administration, the "right time" means administering medication within what window of the scheduled time stated in the doctor''s order?', '["15 minutes before to 15 minutes after", "30 minutes before to 30 minutes after", "1 hour before to 1 hour after", "Any time during the scheduled shift"]'::jsonb, '["15 minutes before to 15 minutes after", "30 minutes before to 30 minutes after", "1 hour before to 1 hour after", "Any time during the scheduled shift"]'::jsonb, 2, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('4dea7348-cf96-5b28-b280-39e79ff5e88d', 1, 'When do standard precautions apply?', 'When do standard precautions apply?', '["Only with clients known to have infectious diseases", "Only when there is visible blood", "For all clients at all times in all contacts", "Only when administering injections"]'::jsonb, '["Only with clients known to have infectious diseases", "Only when there is visible blood", "For all clients at all times in all contacts", "Only when administering injections"]'::jsonb, 3, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('4dea7348-cf96-5b28-b280-39e79ff5e88d', 2, 'What is the single most important measure to prevent contamination and the spread of infection?', 'What is the single most important measure to prevent contamination and the spread of infection?', '["Wearing gloves", "Hand washing", "Wearing a mask", "Disinfecting surfaces"]'::jsonb, '["Wearing gloves", "Hand washing", "Wearing a mask", "Disinfecting surfaces"]'::jsonb, 2, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('4dea7348-cf96-5b28-b280-39e79ff5e88d', 3, 'How many times must you cross-check the medication label against the MAR and physician''s order during administration?', 'How many times must you cross-check the medication label against the MAR and physician''s order during administration?', '["Once", "Twice", "Three times", "Four times"]'::jsonb, '["Once", "Twice", "Three times", "Four times"]'::jsonb, 3, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('4dea7348-cf96-5b28-b280-39e79ff5e88d', 4, 'When administering nitroglycerin SL tablets to a client experiencing chest pain, the client should be instructed to:', 'When administering nitroglycerin SL tablets to a client experiencing chest pain, the client should be instructed to:', '["Lie down flat", "Sit down", "Walk around to improve circulation", "Stand with arms raised"]'::jsonb, '["Lie down flat", "Sit down", "Walk around to improve circulation", "Stand with arms raised"]'::jsonb, 2, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('4dea7348-cf96-5b28-b280-39e79ff5e88d', 5, 'When applying a transdermal patch, which of the following must you do?', 'When applying a transdermal patch, which of the following must you do?', '["Apply it to the same site each time for consistency", "Cut the patch in half if a smaller dose is needed", "Write your initials, date, and time on the patch after applying", "Leave the old patch in place to ensure continuous dosing"]'::jsonb, '["Apply it to the same site each time for consistency", "Cut the patch in half if a smaller dose is needed", "Write your initials, date, and time on the patch after applying", "Leave the old patch in place to ensure continuous dosing"]'::jsonb, 3, '', '');
