insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('4dea7348-cf96-5b28-b280-39e79ff5e88d', 8, 'Which of the following best defines a medication error?', 'Which of the following best defines a medication error?', '["Any time medication is given a few minutes late", "Medication administered contrary to a physician''s order that either causes or has the potential to cause harm", "Only errors that result in hospitalization", "Forgetting to wear gloves during administration"]'::jsonb, '["Any time medication is given a few minutes late", "Medication administered contrary to a physician''s order that either causes or has the potential to cause harm", "Only errors that result in hospitalization", "Forgetting to wear gloves during administration"]'::jsonb, 2, '', '');
