insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('9bd94fda-cec4-54bf-90c6-82dfb47cc1b7', 0, 'What is the purpose of Respite Care?', '¿Cuál es el propósito del Cuidado de Respiro?', '["To permanently replace the primary caregiver", "To provide temporary relief for primary caregivers while ensuring continued safe care", "To evaluate the primary caregiver''s performance", "To transition the individual to a new living arrangement"]'::jsonb, '["Reemplazar permanentemente al cuidador principal", "Proporcionar alivio temporal a los cuidadores principales mientras se asegura la atención continua y segura", "Evaluar el desempeño del cuidador principal", "Trasladar al individuo a un nuevo arreglo de vivienda"]'::jsonb, 2, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('9bd94fda-cec4-54bf-90c6-82dfb47cc1b7', 1, 'Is Respite guaranteed for all caregivers who request it?', '¿Está garantizado el Respiro para todos los cuidadores que lo soliciten?', '["Yes, all requests are automatically approved", "Yes, as long as the request is submitted on time", "No, availability depends on provider availability and the individual''s needs", "No, only Host Home Providers may request Respite"]'::jsonb, '["Sí, todas las solicitudes se aprueban automáticamente", "Sí, siempre que la solicitud se envíe a tiempo", "No, la disponibilidad depende de la disponibilidad del proveedor y las necesidades del individuo", "No, solo los Proveedores de Hogar Anfitrión pueden solicitar Respiro"]'::jsonb, 3, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('9bd94fda-cec4-54bf-90c6-82dfb47cc1b7', 2, 'Which of the following is NOT a requirement for Respite Providers?', '¿Cuál de los siguientes NO es un requisito para los Proveedores de Respiro?', '["Background check", "CPR/First Aid certification", "A college degree in healthcare", "QMAP certification"]'::jsonb, '["Verificación de antecedentes", "Certificación de RCP/Primeros Auxilios", "Un título universitario en salud", "Certificación QMAP"]'::jsonb, 3, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('9bd94fda-cec4-54bf-90c6-82dfb47cc1b7', 3, 'Who is responsible for preparing and sending medications for respite?', '¿Quién es responsable de preparar y enviar los medicamentos para el respiro?', '["The Respite Provider", "The Program Support Coordinator", "The Primary Provider", "The pharmacy"]'::jsonb, '["El Proveedor de Respiro", "El Coordinador de Apoyo de Programas", "El Proveedor Principal", "La farmacia"]'::jsonb, 3, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('9bd94fda-cec4-54bf-90c6-82dfb47cc1b7', 4, 'Incident Reports during respite must be submitted within what timeframe?', '¿Los Reportes de Incidentes durante el respiro deben enviarse dentro de qué plazo?', '["48–72 hours", "24 hours", "1 week", "By the end of the month"]'::jsonb, '["48 a 72 horas", "24 horas", "1 semana", "Antes del final del mes"]'::jsonb, 2, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('9bd94fda-cec4-54bf-90c6-82dfb47cc1b7', 5, 'If respite occurs between the 1st and the 22nd, when should timesheets be submitted?', 'Si el respiro ocurre entre el 1ro y el 22, ¿cuándo deben enviarse las hojas de tiempo?', '["Immediately after respite ends", "By the 3rd of the following month", "By the 22nd", "By the last day of the month"]'::jsonb, '["Inmediatamente después de que termine el respiro", "Antes del 3ro del mes siguiente", "Antes del 22", "Antes del último día del mes"]'::jsonb, 3, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('9bd94fda-cec4-54bf-90c6-82dfb47cc1b7', 6, 'On the Primary Provider''s attendance record, how is a respite day marked?', 'En el registro de asistencia del Proveedor Principal, ¿cómo se marca un día de respiro?', '["With an X", "With an R", "With an S", "It is left blank"]'::jsonb, '["Con una X", "Con una R", "Con una S", "Se deja en blanco"]'::jsonb, 2, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('9bd94fda-cec4-54bf-90c6-82dfb47cc1b7', 7, 'What must each Respite Provider do regarding documentation?', '¿Qué debe hacer cada Proveedor de Respiro respecto a la documentación?', '["Submit documentation through the Primary Provider", "Submit their own documentation separately", "Only submit an Incident Report if something goes wrong", "No documentation is required for Respite"]'::jsonb, '["Enviar la documentación a través del Proveedor Principal", "Enviar su propia documentación por separado", "Solo enviar un Reporte de Incidente si algo sale mal", "No se requiere documentación para el Respiro"]'::jsonb, 2, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('9bd94fda-cec4-54bf-90c6-82dfb47cc1b7', 8, 'When is the Respite Provider typically paid?', '¿Cuándo se le paga típicamente al Proveedor de Respiro?', '["Before respite begins", "On the last day of respite", "Around the 18th of the following month, after documentation is processed", "Within 48 hours of respite ending"]'::jsonb, '["Antes de que comience el respiro", "El último día del respiro", "Alrededor del 18 del mes siguiente, después de que se procesa la documentación", "Dentro de 48 horas de que termina el respiro"]'::jsonb, 3, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('9bd94fda-cec4-54bf-90c6-82dfb47cc1b7', 9, 'What must all Respite Providers review and sign before providing services?', '¿Qué deben revisar y firmar todos los Proveedores de Respiro antes de proporcionar servicios?', '["The Primary Provider''s employment contract", "The Respite Care Provider Acknowledgement Packet", "A liability waiver only", "The agency''s marketing materials"]'::jsonb, '["El contrato de empleo del Proveedor Principal", "El Paquete de Reconocimiento del Proveedor de Cuidado de Respiro", "Solo una exención de responsabilidad", "Los materiales de marketing de la agencia"]'::jsonb, 2, '', '');
insert into public.courses (id, slug, title_en, title_es, description_en, description_es, sort, is_specialty, price_cents) values ('fa6cac84-3366-5c45-bbde-b6d07e699f72', 'documentation', 'Documentation Submissions & Compliance', 'Entrega de documentación y cumplimiento', 'Monthly deadlines, what to submit, how submissions are reviewed, and what happens when paperwork is late.', 'Fechas límite mensuales, qué entregar, cómo se revisan las entregas y qué pasa cuando la documentación llega tarde.', 16, false, 1000);
insert into public.lessons (id, course_id, sort, kind, title_en, title_es, body_en, body_es, video_url, video_seconds, video_source) values ('6baa65e4-e457-5992-bfc9-3ceda955f00c', 'fa6cac84-3366-5c45-bbde-b6d07e699f72', 0, 'video', 'Watch the training', 'Vea la capacitación', 'Welcome to Real Care! This training covers Documentation Submissions and Compliance. Accurate, timely documentation is one of the most important parts of what we do. It ensures compliance with state regulations, supports billing and funding, and protects the health and safety of the individuals we serve. Please listen carefully and take note of the key deadlines and requirements covered here.

First, let''s review the provider types you will be working with. Host Home Providers, or HHPs, are non-related caregivers who provide twenty-four-hour care in their own homes and can serve up to three clients at a time. Family Caregivers, or FCGs, are related individuals who provide daily support in the individual''s own home. Direct Support Professionals, or DSPs, provide residential services in the individual''s or family home on an hourly basis. Respite Providers give temporary relief to primary caregivers. Supported Community Connection Providers, or SCCs, provide community-based hourly services. And Non-Medical Transportation Providers, or NMTs, transport clients to or from day programs or work.

An important concept to understand is Natural Support versus No Natural Support. Natural Supports are unpaid individuals — such as family members, friends, or guardians — who assist with care and supervision. They may help with medication oversight, meals and nutritional support, transportation, and financial management. This distinction matters because it affects documentation requirements. In Family Caregiver settings where Natural Support is present, medication documentation may be completed through Log Notes with Medication Verification. MARs are not required unless specifically directed by an RCI Coordinator or Manager. Meals and nutritional documentation is also not required unless directed by a doctor or coordinator. However, in Family Caregiver settings without Natural Support, the caregiver is fully responsible for all medication administration, meals, transportation, and financial management. This means MARs, Narcotic Records when applicable, and Quarterly Menu Tracking are all required. Important note: Host Home Providers, Respite Providers, Direct Support Professionals, Supported Community Connection Providers, and Non-Medical Transportation Providers do not have Natural Supports. All care responsibilities rest solely with the provider.

Now let''s go over submission frequency. There are four categories: monthly, quarterly, as-needed, and annually. The major processing window runs from the first through the tenth of each month, and the attendance and timesheet processing window runs from the twentieth through the twenty-second.

For monthly submissions, most documents are due by the third of each month. Let''s walk through each one.

Weekly Log Notes are required for Family Caregivers, Host Home Providers, Direct Support Professionals, and Respite Providers. Log Notes serve as the primary record of weekly service delivery, confirming that authorized services were provided as outlined in the Service Plan. They document health, safety, and behavioral changes that may require follow-up. They support medication oversight when applicable and provide evidence of progress toward ISP goals. This documentation is used for compliance review, audits, and accurate database entry. Log Notes must be legible and complete, dated and signed, cover the full reporting period, be consistent with authorized services and the provider''s role, and submitted by the required deadline.

ISP and Goal Tracking is required for Family Caregivers, Host Home Providers, Direct Support Professionals, Respite Providers, and Supported Community Connection Providers. Every individual must have at least one goal, show ongoing weekly progress toward each goal, and show the level of provider support or the individual''s independence. Goal tracking may appear on a Goal Tracking Sheet, in Weekly Log Notes, or on a Protocol Tracking Sheet. Real Care personalizes paperwork to best set up caregivers and providers for success.

Daily Receipts of Care are required for all Host Home Providers and Direct Support Professionals unless an approved exception exists. These demonstrate to the state that care is being provided every day, which ensures funding through the daily rate. This may include Protocol Tracking, Rights Modification Tracking, or Residential Tracking. When reviewing these documents, verify that daily receipts are complete, accurate, and submitted on time. Check that daily care is documented consistently, and look for trends or gaps that may require follow-up.

Medication documentation is also due by the third. Depending on the setting, providers submit either MARs and Narcotic Records, Log Notes with Medication Verification, or Log Notes with Self-Med Verification if the individual self-administers medications. Some individuals may have no current prescriptions.

Financial records are due by the third when Real Care is the Representative Payee. This includes the Community Account Record form, which documents all personal spending and deposits, receipts as proof of purchases from Personal Needs Funds, and bank statements to verify account balances. Make sure receipts match the amounts reported on the CAR form and review all documents for completeness.

Attendance records and timesheets have a separate deadline — they are due by the twenty-second of each month. Family Caregivers, Host Home Providers, and Respite Providers submit daily attendance records. Direct Support Professionals and Supported Community Connection Providers submit hourly timesheets. Non-Medical Transportation Providers submit trips, where each trip equals one unit, with a maximum of two trips daily and eight trips weekly. Key monthly deadlines to remember: the eighteenth is when processing begins, the twentieth is the standard processing start, noon on the twenty-second is the first reminder, the twenty-fifth is when processed records and the roster are submitted to Ed, and the first of the following month is the deadline for final corrections and escalation.

For quarterly submissions, Fire and Disaster Drills are required for all individuals and are completed with the Family Caregiver, Host Home Provider, or Direct Support Professional. Menu Tracking is required for Family Caregivers without Natural Support and for Host Home Providers, and also when a medically prescribed diet exists.

For as-needed submissions, Incident Reports must be submitted within twenty-four to forty-eight hours. They are required for all caregivers and providers, and timely reporting is critical. Forward Incident Reports to Real Care staff as soon as possible. Medical Appointment documentation is also submitted as needed — providers are responsible for attendance and documentation.

Annual medical requirements include Medication Orders, PRN and OTC Orders, Adaptive Equipment Checklists when applicable, Physical exams, Dental visits at least twice per year, Vision exams every one to two years, and visits to Specialty Providers such as neurology, psychology, cardiology, or oncology.

Now let''s cover the processing workflow and documentation standards. The big picture is: receive and open the email, review attachments, print and prep documents, log in the roster and database, identify issues, communicate with the provider, file and organize, and track follow-ups.

For email processing, fully process one email at a time, starting with the oldest submissions first. If you receive multiple emails from the same provider, process them together. Leave unresolved emails in the Inbox or Pending Issues folder. For printing, use single-sided only, correct orientation, and make sure documents are legible and cropped. Enhance scans with CamScanner if needed. Do not print dark, tiny, or unreadable images, and do not mass print.

When verifying documents, highlight and confirm the client name, provider name, month and year, total days or hours or units, and the provider''s signature and date. If a name or date is missing, write it neatly and initial. If a signature is missing, email the provider, use DocuSign if needed, and document it on the roster.

The client database uses color coding: Green means new service, client, or document. Yellow means one to two months non-compliant. Red means two or more months overdue and escalated. White means fully compliant. Log entries before moving to the next email, use clear and complete notes, and use approved acronyms only.

For provider communication, responses must acknowledge what was received, clearly state what is missing, recap all items when multiple emails exist, use approved templates only, and maintain a calm, professional tone. Reminder emails follow a schedule: noon on the twenty-second is the first reminder, noon on the twenty-fifth is the final reminder, and between the twenty-sixth and the first you may send one follow-up maximum. No daily or unscheduled reminders. Escalation triggers include documentation that is thirty or sixty or more days overdue, database entries that don''t match documents, provider disputes, repeated errors or refusals, and deadlines at risk.

As a Documentation Support Coordinator, you are the central hub for documentation intake, tracking, and follow-up. Your role ensures compliance, accurate billing, and uninterrupted payments. The focus is on tracking and escalation — not perfection. Your primary goals are to receive and process documentation accurately and on time, prevent billing interruptions and payment delays, maintain compliance with service authorizations and deadlines, and provide clear, supportive communication to providers.

Thank you for completing the Documentation Submissions and Compliance training. If you have any questions, please contact Real Care staff.', 'Bienvenido a Real Care. Esta capacitación cubre el Envío de Documentación y Cumplimiento. La documentación precisa y oportuna es una de las partes más importantes de lo que hacemos. Asegura el cumplimiento con las regulaciones estatales, apoya la facturación y el financiamiento, y protege la salud y seguridad de las personas que servimos. Por favor escuche con atención y tome nota de las fechas límite y requisitos clave que se cubren aquí.

Primero, revisemos los tipos de proveedores con los que trabajará. Los Proveedores de Hogar Anfitrión, o HHPs, son cuidadores no relacionados que proporcionan atención las veinticuatro horas en sus propios hogares y pueden atender hasta tres clientes a la vez. Los Cuidadores Familiares, o FCGs, son personas relacionadas que proporcionan apoyo diario en el hogar del individuo. Los Profesionales de Apoyo Directo, o DSPs, proporcionan servicios residenciales por hora en el hogar del individuo o de la familia. Los Proveedores de Respiro dan alivio temporal a los cuidadores principales. Los Proveedores de Conexión Comunitaria con Apoyo, o SCCs, proporcionan servicios comunitarios por hora. Y los Proveedores de Transporte No Médico, o NMTs, transportan a los clientes hacia y desde programas diurnos o trabajo.

Un concepto importante que debe entender es el de Apoyo Natural versus Sin Apoyo Natural. Los Apoyos Naturales son personas no remuneradas — como familiares, amigos o tutores — que ayudan con el cuidado y la supervisión. Pueden ayudar con la supervisión de medicamentos, comidas y apoyo nutricional, transporte y gestión financiera. Esta distinción importa porque afecta los requisitos de documentación. En entornos de Cuidadores Familiares donde hay Apoyo Natural presente, la documentación de medicamentos puede completarse a través de Notas de Registro con Verificación de Medicamentos. Los MARs no son requeridos a menos que lo indique específicamente un Coordinador o Gerente de RCI. La documentación de comidas y nutrición tampoco es requerida a menos que lo indique un médico o coordinador. Sin embargo, en entornos de Cuidadores Familiares sin Apoyo Natural, el cuidador es totalmente responsable de toda la administración de medicamentos, comidas, transporte y gestión financiera. Esto significa que los MARs, Registros de Narcóticos cuando aplique, y el Seguimiento Trimestral de Menús son todos requeridos. Nota importante: los Proveedores de Hogar Anfitrión, Proveedores de Respiro, Profesionales de Apoyo Directo, Proveedores de Conexión Comunitaria y Proveedores de Transporte No Médico no tienen Apoyos Naturales. Todas las responsabilidades de cuidado recaen únicamente en el proveedor.

Ahora revisemos la frecuencia de envío. Hay cuatro categorías: mensual, trimestral, según sea necesario y anual. La ventana principal de procesamiento va del primero al diez de cada mes, y la ventana de procesamiento de asistencia y hojas de tiempo va del veinte al veintidós.

Para los envíos mensuales, la mayoría de los documentos vencen el tercero de cada mes.

Las Notas de Registro Semanales son requeridas para Cuidadores Familiares, Proveedores de Hogar Anfitrión, Profesionales de Apoyo Directo y Proveedores de Respiro. Las Notas de Registro sirven como el registro principal de la prestación de servicios semanales, confirmando que los servicios autorizados fueron proporcionados según lo establecido en el Plan de Servicios. Documentan cambios de salud, seguridad y comportamiento que pueden requerir seguimiento. Apoyan la supervisión de medicamentos cuando aplica y proporcionan evidencia de progreso hacia las metas del ISP. Esta documentación se usa para revisión de cumplimiento, auditorías y entrada precisa en la base de datos. Las Notas de Registro deben ser legibles y completas, fechadas y firmadas, cubrir todo el período de reporte, ser consistentes con los servicios autorizados y el rol del proveedor, y enviadas antes de la fecha límite.

El Seguimiento de ISP y Metas es requerido para Cuidadores Familiares, Proveedores de Hogar Anfitrión, Profesionales de Apoyo Directo, Proveedores de Respiro y Proveedores de Conexión Comunitaria. Cada individuo debe tener al menos una meta, mostrar progreso semanal continuo hacia cada meta y mostrar el nivel de apoyo del proveedor o la independencia del individuo. El seguimiento de metas puede aparecer en una Hoja de Seguimiento de Metas, en las Notas de Registro Semanales o en una Hoja de Seguimiento de Protocolo.

Los Recibos Diarios de Atención son requeridos para todos los Proveedores de Hogar Anfitrión y Profesionales de Apoyo Directo a menos que exista una excepción aprobada. Estos demuestran al estado que se está proporcionando atención todos los días, lo cual asegura el financiamiento a través de la tarifa diaria. Esto puede incluir Seguimiento de Protocolo, Seguimiento de Modificación de Derechos o Seguimiento Residencial.

La documentación de medicamentos también vence el tercero. Dependiendo del entorno, los proveedores envían MARs y Registros de Narcóticos, Notas de Registro con Verificación de Medicamentos, o Notas de Registro con Verificación de Auto-Medicación si el individuo se auto-administra medicamentos.

Los registros financieros vencen el tercero cuando Real Care es el Representante de Pagos. Esto incluye el formulario de Registro de Cuenta Comunitaria que documenta todos los gastos y depósitos personales, recibos como prueba de compras de los Fondos de Necesidades Personales y estados de cuenta bancarios para verificar saldos y transacciones. Asegúrese de que los recibos coincidan con los montos reportados en el formulario CAR.

Los registros de asistencia y hojas de tiempo tienen una fecha límite diferente — vencen el veintidós de cada mes. Los Cuidadores Familiares, Proveedores de Hogar Anfitrión y Proveedores de Respiro envían registros de asistencia diaria. Los Profesionales de Apoyo Directo y Proveedores de Conexión Comunitaria envían hojas de tiempo por hora. Los Proveedores de Transporte No Médico envían viajes, donde cada viaje equivale a una unidad, con un máximo de dos viajes diarios y ocho por semana. Fechas límite mensuales clave: el dieciocho comienza el procesamiento, el veinte es el inicio estándar del procesamiento, el mediodía del veintidós es el primer recordatorio, el veinticinco se envían los registros procesados y el listado a Ed, y el primero del mes siguiente es la fecha límite para correcciones finales y escalación.

Para envíos trimestrales, los Simulacros de Incendio y Desastres son requeridos para todos los individuos. El Seguimiento de Menús es requerido para Cuidadores Familiares sin Apoyo Natural y para Proveedores de Hogar Anfitrión, y cuando existe una dieta prescrita médicamente.

Para envíos según sea necesario, los Reportes de Incidentes deben enviarse dentro de veinticuatro a cuarenta y ocho horas. Son requeridos para todos los cuidadores y proveedores, y la puntualidad es crítica. Envíe los Reportes de Incidentes al personal de Real Care lo antes posible. La documentación de Citas Médicas también se envía según sea necesario.

Los requisitos médicos anuales incluyen Órdenes de Medicamentos, Órdenes PRN y OTC, Listas de Verificación de Equipo Adaptativo cuando aplique, Exámenes Físicos, Visitas Dentales al menos dos veces al año, Exámenes de la Vista cada uno a dos años y visitas a Proveedores Especialistas como neurología, psicología, cardiología u oncología.

Respecto al flujo de trabajo de procesamiento: reciba y abra el correo electrónico, revise los archivos adjuntos, imprima y prepare los documentos, regístrelos en el listado y la base de datos, identifique problemas, comuníquese con el proveedor, archive y organice, y haga seguimiento.

Para el procesamiento de correos, procese completamente un correo a la vez, comenzando con los envíos más antiguos primero. Si recibe múltiples correos del mismo proveedor, procéselos juntos. Para la impresión, use una sola cara, orientación correcta, y asegúrese de que los documentos sean legibles. No imprima en masa.

Al verificar documentos, resalte y confirme el nombre del cliente, nombre del proveedor, mes y año, total de días u horas o unidades, y la firma y fecha del proveedor. Si falta un nombre o fecha, escríbalo claramente e inicialice. Si falta una firma, envíe un correo al proveedor, use DocuSign si es necesario y documente en el listado.

La base de datos del cliente usa codificación de colores: Verde significa nuevo servicio, cliente o documento. Amarillo significa uno a dos meses sin cumplimiento. Rojo significa dos o más meses vencidos y escalado. Blanco significa completamente en cumplimiento.

Para la comunicación con proveedores, las respuestas deben reconocer lo que se recibió, indicar claramente lo que falta, recapitular todos los elementos cuando existen múltiples correos, usar solo plantillas aprobadas y mantener un tono calmado y profesional. Los correos de recordatorio siguen un calendario: mediodía del veintidós es el primer recordatorio, mediodía del veinticinco es el recordatorio final, y entre el veintiséis y el primero puede enviar un máximo de un seguimiento. No se permiten recordatorios diarios o no programados.

Como Coordinador de Apoyo de Documentación, usted es el centro de recepción, seguimiento y seguimiento de documentación. Su rol asegura el cumplimiento, la facturación precisa y los pagos ininterrumpidos. El enfoque es en el seguimiento y la escalación — no la perfección.

Gracias por completar la capacitación de Envío de Documentación y Cumplimiento. Si tiene alguna pregunta, por favor contacte al personal de Real Care.', 'courses/fa6cac84-3366-5c45-bbde-b6d07e699f72/documentation.mp4', 765, 'file');
