insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('bfdbdb5c-249d-5c20-9d72-e21f81da63c7', 0, 'Most monthly documentation (Log Notes, Goal Tracking, MARs, Daily Receipts of Care) is due by which date?', '¿La mayoría de la documentación mensual (Notas de Registro, Seguimiento de Metas, MARs, Recibos Diarios de Atención) debe entregarse antes de qué fecha?', '["The 1st", "The 3rd", "The 10th", "The 22nd"]'::jsonb, '["El 1ro", "El 3ro", "El 10", "El 22"]'::jsonb, 2, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('bfdbdb5c-249d-5c20-9d72-e21f81da63c7', 1, 'What are "Natural Supports"?', '¿Qué son los "Apoyos Naturales"?', '["Paid staff hired by Real Care to assist caregivers", "State-funded support workers assigned to each client", "Unpaid individuals such as family members or friends who assist with care", "Medical equipment provided to the home"]'::jsonb, '["Personal pagado contratado por Real Care para asistir a los cuidadores", "Trabajadores de apoyo financiados por el estado asignados a cada cliente", "Personas no remuneradas como familiares o amigos que ayudan con el cuidado", "Equipo médico proporcionado al hogar"]'::jsonb, 3, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('bfdbdb5c-249d-5c20-9d72-e21f81da63c7', 2, 'Attendance records and timesheets are due by which date each month?', '¿Los registros de asistencia y hojas de tiempo deben entregarse antes de qué fecha cada mes?', '["The 3rd", "The 10th", "The 15th", "The 22nd"]'::jsonb, '["El 3ro", "El 10", "El 15", "El 22"]'::jsonb, 4, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('bfdbdb5c-249d-5c20-9d72-e21f81da63c7', 3, 'What is the maximum number of NMT trips allowed per week?', '¿Cuál es el número máximo de viajes de NMT permitidos por semana?', '["4", "6", "8", "10"]'::jsonb, '["4", "6", "8", "10"]'::jsonb, 3, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('bfdbdb5c-249d-5c20-9d72-e21f81da63c7', 4, 'Within what timeframe must Incident Reports be submitted?', '¿Dentro de qué plazo deben enviarse los Reportes de Incidentes?', '["Within 1 week", "Within 24–48 hours", "By the end of the month", "Within 30 days"]'::jsonb, '["Dentro de 1 semana", "Dentro de 24 a 48 horas", "Antes del final del mes", "Dentro de 30 días"]'::jsonb, 2, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('bfdbdb5c-249d-5c20-9d72-e21f81da63c7', 5, 'In the client database, what does the color RED indicate?', 'En la base de datos del cliente, ¿qué indica el color ROJO?', '["New service, client, or document", "Fully compliant", "1–2 months non-compliant", "2+ months overdue and escalated"]'::jsonb, '["Nuevo servicio, cliente o documento", "Completamente en cumplimiento", "1 a 2 meses sin cumplimiento", "2 o más meses vencidos y escalado"]'::jsonb, 4, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('bfdbdb5c-249d-5c20-9d72-e21f81da63c7', 6, 'Which of the following providers is required to submit Daily Receipts of Care?', '¿Cuál de los siguientes proveedores debe enviar Recibos Diarios de Atención?', '["SCC Providers", "NMT Providers", "Host Home Providers", "Family Caregivers with Natural Support"]'::jsonb, '["Proveedores de SCC", "Proveedores de NMT", "Proveedores de Hogar Anfitrión", "Cuidadores Familiares con Apoyo Natural"]'::jsonb, 3, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('bfdbdb5c-249d-5c20-9d72-e21f81da63c7', 7, 'How should emails be processed?', '¿Cómo deben procesarse los correos electrónicos?', '["Newest submissions first, multiple at a time", "One email at a time, oldest submissions first", "Only emails with attachments need to be processed", "Process all emails at the end of the week"]'::jsonb, '["Los más recientes primero, varios a la vez", "Un correo a la vez, los más antiguos primero", "Solo los correos con archivos adjuntos necesitan procesarse", "Procesar todos los correos al final de la semana"]'::jsonb, 2, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('bfdbdb5c-249d-5c20-9d72-e21f81da63c7', 8, 'Fire and Disaster Drills are submitted on what schedule?', '¿Los Simulacros de Incendio y Desastres se envían con qué frecuencia?', '["Monthly", "Quarterly", "Annually", "As needed"]'::jsonb, '["Mensualmente", "Trimestralmente", "Anualmente", "Según sea necesario"]'::jsonb, 2, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('bfdbdb5c-249d-5c20-9d72-e21f81da63c7', 9, 'What is the primary focus of the Documentation Support Coordinator role?', '¿Cuál es el enfoque principal del rol de Coordinador de Apoyo de Documentación?', '["Perfecting every document before filing", "Tracking and escalation — not perfection", "Writing provider correspondence from scratch", "Conducting home inspections"]'::jsonb, '["Perfeccionar cada documento antes de archivarlo", "Seguimiento y escalación — no la perfección", "Escribir correspondencia de proveedores desde cero", "Realizar inspecciones del hogar"]'::jsonb, 2, '', '');
insert into public.courses (id, slug, title_en, title_es, description_en, description_es, sort, is_specialty, price_cents) values ('cc186201-fff4-5a7d-b392-76faa3f53c12', 'injection-admin', 'RCI Injection Administration', 'Administración de inyecciones (RCI)', 'Giving delegated injections safely: nurse delegation, preparation, sharps, reactions and documentation.', 'Cómo aplicar inyecciones delegadas de forma segura: delegación de enfermería, preparación, objetos punzantes, reacciones y documentación.', 17, true, 1000);
insert into public.lessons (id, course_id, sort, kind, title_en, title_es, body_en, body_es, video_url, video_seconds, video_source) values ('e7c693de-e133-5157-aa25-6f549db1a25e', 'cc186201-fff4-5a7d-b392-76faa3f53c12', 0, 'video', 'Watch the training', 'Vea la capacitación', 'Welcome to Real Care! This training covers Injection Administration under Delegated Medication Administration. By the end of this training, you will be able to explain why injections are used, understand nurse delegation requirements, identify the supplies needed, demonstrate proper injection technique, follow infection control practices, recognize adverse reactions, safely dispose of sharps, and document medication administration correctly. Please note that caregivers and providers will also need to demonstrate competency during nurse observation.

Let''s begin with the nurse delegation overview. Injection administration may only be performed when three conditions are met. First, a licensed Real Care, Inc. nurse must delegate the task to you. Second, you must receive training and demonstration. And third, you must complete competency verification. Delegation includes written instructions, protocol guidance, competency validation, and ongoing supervision. This process follows several regulations, including the Colorado Nurse Practice Act, Colorado Revised Statutes Section 12-255-131 on Delegation of Nursing Tasks, Colorado Board of Nursing Rule 3 CCR 716-1.13, HCPF IDD Waiver requirements, CDPHE infection control guidance, and Real Care agency policies and procedures.

Now let''s talk about why injections are used. Medications are given by injection to deliver medication quickly into the body, provide medications that cannot be taken by mouth, manage chronic conditions such as diabetes or hormone therapy, and maintain consistent medication levels in the bloodstream. Proper technique is critical because it prevents infection, tissue damage, medication errors, and individual discomfort.

There are two types of injections you may administer. Subcutaneous injections, also called SubQ, deliver medication into the fat layer under the skin. Common medications given this way include insulin and some hormone medications. Typical injection sites are the abdomen, upper arm, and thigh. Intramuscular injections, also called IM, deliver medication into muscle tissue. Muscles absorb medication faster than fat tissue. Common sites for intramuscular injections include the deltoid or upper arm, the thigh, and the hip.

Before every injection, you must verify the Seven Rights of Medication Administration. These are: the Right Person — make sure you are giving the medication to the correct individual. The Right Medication — verify the medication matches the order. The Right Dose — confirm the amount is correct. The Right Route — ensure it is being given subcutaneously or intramuscularly as ordered. The Right Time — administer at the correct time. The Right Documentation — record everything accurately. And the Right Reason — understand why the medication is being given. Failure to verify these rights can result in serious medication errors.

There are situations when you should not give an injection. Do not administer medication if the medication appears contaminated, if the medication is expired, if the individual has a known allergy, if the injection site is red, swollen, bruised, or infected, if the medication order is unclear, or if the syringe or needle is damaged. In any of these situations, contact the prescriber, pharmacy, or nurse.

Before beginning, gather all required supplies. You will need the prescribed medication, a syringe and needle if not using a prefilled syringe, alcohol swabs, gloves, a sharps container, the Medication Administration Record or MAR, and a clean preparation surface. Never begin the procedure without all required supplies.

Infection control is essential and protects both you and the individual. Always wash your hands before and after the procedure, wear gloves, use sterile needles and syringes, clean the injection site with alcohol, and never reuse needles or syringes. Improper infection control can cause bloodborne infections, skin infections, and other serious complications.

Now let''s walk through the preparation steps. To prepare the medication: first, perform hand hygiene. Second, put on gloves. Third, verify the medication order with the MAR. Fourth, check the medication label and expiration date. And fifth, prepare the medication according to nurse instructions. Never prepare medication if you are unsure about the instructions. To prepare the individual: first, explain the procedure to them. Second, ensure their privacy and dignity. Third, position them comfortably. And fourth, select the correct injection site. Some individuals prefer being informed before the injection, sitting or lying down, or using distraction techniques. Respect their preferences.

For the injection itself, follow these steps. First, clean the injection site with an alcohol swab. Second, allow the site to dry completely. Third, position the needle according to the injection type. Fourth, insert the needle at the proper angle. Fifth, inject the medication slowly. Sixth, remove the needle carefully. And seventh, apply pressure or a bandage if needed.

Immediately after the injection, dispose of the needle in the sharps container, remove your gloves, wash your hands, observe the individual for reactions, and provide reassurance and comfort. Never place used needles in regular trash.

Safe sharps disposal is critical. Always dispose of needles immediately, use an approved sharps container, never recap needles, never bend or break needles, and never leave sharps unattended. Improper sharps disposal can cause needlestick injuries and bloodborne pathogen exposure.

You need to know the difference between normal and concerning reactions. Normal reactions may include mild soreness and minor redness at the injection site. However, report immediately if you observe severe pain, swelling, rash, difficulty breathing, dizziness, or nausea and vomiting. Signs of a severe allergic reaction include swelling of the lips, face, or throat, difficulty breathing, rapid heartbeat, and severe dizziness. If any of these occur, take these actions: stop the procedure, notify the nurse immediately, follow emergency protocol, and call nine-one-one if the situation is life-threatening.

Documentation must happen immediately after each injection. Record the following on the MAR: the medication name, the dose administered, the route — whether SubQ or IM, the injection site used, the date and time, and any reactions observed. Accurate documentation ensures safe medication tracking, regulatory compliance, and continuity of care.

Let''s review when to contact the nurse. Notify Real Care if a medication error occurs, if the individual refuses medication, if an adverse reaction occurs, if the injection site looks abnormal, or if there is a medication supply issue. Incident Reporting may be required. Prompt reporting protects the individual''s health and safety.

As a delegated staff member, your responsibilities include following written instructions and injection protocol, maintaining infection control practices, respecting individual preferences, documenting accurately, and reporting concerns immediately. Injection administration cannot be delegated to untrained staff.

Finally, let''s discuss competency demonstration. A Real Care nurse will verify your hand hygiene, medication preparation, correct injection technique, infection control practices, safe sharps disposal, proper documentation, and your ability to recognize adverse reactions. To complete this training, you must review the injection policy and protocol, demonstrate competency with a nurse, and sign the acknowledgment form. Competency is reassessed annually, when care plans change, and if incidents occur. Competency may also be verified via video observation.

Thank you for completing the Injection Administration training. If you have any questions, please contact Real Care staff.', 'Bienvenido a Real Care. Esta capacitación cubre la Administración de Inyecciones bajo la Administración Delegada de Medicamentos. Al final de esta capacitación, podrá explicar por qué se usan las inyecciones, comprender los requisitos de delegación de enfermería, identificar los suministros necesarios, demostrar la técnica correcta de inyección, seguir las prácticas de control de infecciones, reconocer reacciones adversas, desechar objetos punzantes de manera segura y documentar correctamente la administración de medicamentos. Tenga en cuenta que los cuidadores y proveedores también deberán demostrar competencia durante la observación de enfermería.

Comencemos con la descripción general de la delegación de enfermería. La administración de inyecciones solo puede realizarse cuando se cumplen tres condiciones. Primero, una enfermera licenciada de Real Care, Inc. debe delegarle la tarea. Segundo, usted debe recibir capacitación y demostración. Y tercero, debe completar la verificación de competencia. La delegación incluye instrucciones escritas, orientación de protocolo, validación de competencia y supervisión continua. Este proceso sigue varias regulaciones, incluyendo la Ley de Práctica de Enfermería de Colorado, los Estatutos Revisados de Colorado Sección 12-255-131 sobre Delegación de Tareas de Enfermería, la Regla 3 CCR 716-1.13 de la Junta de Enfermería de Colorado, los requisitos del Waiver IDD de HCPF, la orientación de control de infecciones de CDPHE y las políticas y procedimientos de la agencia Real Care.

Hablemos de por qué se usan las inyecciones. Los medicamentos se administran por inyección para entregar medicamentos rápidamente al cuerpo, proporcionar medicamentos que no pueden tomarse por vía oral, manejar condiciones crónicas como la diabetes o la terapia hormonal, y mantener niveles consistentes de medicamentos en el torrente sanguíneo. La técnica adecuada es crítica porque previene infecciones, daño a los tejidos, errores de medicación e incomodidad para el individuo.

Hay dos tipos de inyecciones que puede administrar. Las inyecciones subcutáneas, también llamadas SubQ, entregan medicamentos en la capa de grasa debajo de la piel. Los medicamentos comunes administrados de esta manera incluyen la insulina y algunos medicamentos hormonales. Los sitios típicos de inyección son el abdomen, la parte superior del brazo y el muslo. Las inyecciones intramusculares, también llamadas IM, entregan medicamentos en el tejido muscular. Los músculos absorben los medicamentos más rápido que el tejido graso. Los sitios comunes para inyecciones intramusculares incluyen el deltoides o parte superior del brazo, el muslo y la cadera.

Antes de cada inyección, debe verificar los Siete Derechos de la Administración de Medicamentos. Estos son: la Persona Correcta — asegúrese de que está dando el medicamento a la persona correcta. El Medicamento Correcto — verifique que el medicamento coincida con la orden. La Dosis Correcta — confirme que la cantidad sea correcta. La Ruta Correcta — asegúrese de que se esté administrando subcutáneamente o intramuscularmente según lo ordenado. La Hora Correcta — administre en el momento correcto. La Documentación Correcta — registre todo con precisión. Y la Razón Correcta — entienda por qué se está dando el medicamento. No verificar estos derechos puede resultar en errores graves de medicación.

Hay situaciones en las que no debe administrar una inyección. No administre medicamentos si el medicamento parece contaminado, si el medicamento está vencido, si el individuo tiene una alergia conocida, si el sitio de inyección está rojo, inflamado, con moretones o infectado, si la orden del medicamento no es clara, o si la jeringa o la aguja está dañada. En cualquiera de estas situaciones, contacte al médico prescriptor, la farmacia o la enfermera.

Antes de comenzar, reúna todos los suministros necesarios. Necesitará el medicamento prescrito, una jeringa y aguja si no está usando una jeringa prellenada, toallitas de alcohol, guantes, un contenedor de objetos punzantes, el Registro de Administración de Medicamentos o MAR, y una superficie de preparación limpia. Nunca comience el procedimiento sin todos los suministros requeridos.

El control de infecciones es esencial y protege tanto a usted como al individuo. Siempre lávese las manos antes y después del procedimiento, use guantes, use agujas y jeringas estériles, limpie el sitio de inyección con alcohol y nunca reutilice agujas o jeringas. El control de infecciones inadecuado puede causar infecciones transmitidas por la sangre, infecciones de la piel y otras complicaciones graves.

Ahora repasemos los pasos de preparación. Para preparar el medicamento: primero, realice la higiene de manos. Segundo, póngase los guantes. Tercero, verifique la orden del medicamento con el MAR. Cuarto, revise la etiqueta del medicamento y la fecha de vencimiento. Y quinto, prepare el medicamento según las instrucciones de la enfermera. Nunca prepare medicamentos si no está seguro de las instrucciones. Para preparar al individuo: primero, explíquele el procedimiento. Segundo, asegure su privacidad y dignidad. Tercero, posiciónelo cómodamente. Y cuarto, seleccione el sitio correcto de inyección. Algunos individuos prefieren ser informados antes de la inyección, sentarse o acostarse, o usar técnicas de distracción. Respete sus preferencias.

Para la inyección misma, siga estos pasos. Primero, limpie el sitio de inyección con una toallita de alcohol. Segundo, permita que el sitio se seque completamente. Tercero, posicione la aguja según el tipo de inyección. Cuarto, inserte la aguja en el ángulo adecuado. Quinto, inyecte el medicamento lentamente. Sexto, retire la aguja con cuidado. Y séptimo, aplique presión o una curita si es necesario.

Inmediatamente después de la inyección, deseche la aguja en el contenedor de objetos punzantes, quítese los guantes, lávese las manos, observe al individuo por reacciones y proporcione consuelo y tranquilidad. Nunca coloque las agujas usadas en la basura regular.

El desecho seguro de objetos punzantes es crítico. Siempre deseche las agujas inmediatamente, use un contenedor aprobado de objetos punzantes, nunca vuelva a tapar las agujas, nunca doble o rompa las agujas y nunca deje los objetos punzantes desatendidos. El desecho inadecuado puede causar lesiones por pinchazos de aguja y exposición a patógenos transmitidos por la sangre.

Necesita conocer la diferencia entre reacciones normales y preocupantes. Las reacciones normales pueden incluir dolor leve y enrojecimiento menor en el sitio de inyección. Sin embargo, reporte inmediatamente si observa dolor severo, inflamación, sarpullido, dificultad para respirar, mareos o náuseas y vómitos. Los signos de una reacción alérgica severa incluyen inflamación de los labios, cara o garganta, dificultad para respirar, latidos cardíacos rápidos y mareos severos. Si alguno de estos ocurre, tome estas acciones: detenga el procedimiento, notifique a la enfermera inmediatamente, siga el protocolo de emergencia y llame al nueve-uno-uno si la situación es potencialmente mortal.

La documentación debe realizarse inmediatamente después de cada inyección. Registre lo siguiente en el MAR: el nombre del medicamento, la dosis administrada, la ruta — ya sea SubQ o IM, el sitio de inyección utilizado, la fecha y hora, y cualquier reacción observada. La documentación precisa asegura el seguimiento seguro de medicamentos, el cumplimiento regulatorio y la continuidad de la atención.

Revisemos cuándo contactar a la enfermera. Notifique a Real Care si ocurre un error de medicación, si el individuo rechaza el medicamento, si ocurre una reacción adversa, si el sitio de inyección se ve anormal, o si hay un problema con el suministro de medicamentos. Puede requerirse un Reporte de Incidente. El reporte oportuno protege la salud y seguridad del individuo.

Como personal delegado, sus responsabilidades incluyen seguir las instrucciones escritas y el protocolo de inyección, mantener las prácticas de control de infecciones, respetar las preferencias individuales, documentar con precisión y reportar preocupaciones inmediatamente. La administración de inyecciones no puede delegarse a personal no capacitado.

Finalmente, hablemos de la demostración de competencia. Una enfermera de Real Care verificará su higiene de manos, preparación de medicamentos, técnica correcta de inyección, prácticas de control de infecciones, desecho seguro de objetos punzantes, documentación adecuada y su capacidad para reconocer reacciones adversas. Para completar esta capacitación, debe revisar la política y protocolo de inyección, demostrar competencia con una enfermera y firmar el formulario de reconocimiento. La competencia se reevalúa anualmente, cuando cambian los planes de atención y si ocurren incidentes. La competencia también puede verificarse mediante observación por video.

Gracias por completar la capacitación de Administración de Inyecciones. Si tiene alguna pregunta, por favor contacte al personal de Real Care.', 'courses/cc186201-fff4-5a7d-b392-76faa3f53c12/injection-admin.mp4', 647, 'file');
insert into public.lessons (id, course_id, sort, kind, title_en, title_es, pass_percent) values ('3a72b37d-46e4-5115-aa9a-b169602d24d2', 'cc186201-fff4-5a7d-b392-76faa3f53c12', 1, 'quiz', 'Quiz', 'Prueba', 80);
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('3a72b37d-46e4-5115-aa9a-b169602d24d2', 0, 'Injection administration may only be performed when which conditions are met?', '¿La administración de inyecciones solo puede realizarse cuando se cumplen cuáles condiciones?', '["The caregiver has watched an online video and feels confident", "A licensed Real Care nurse delegates the task, training is provided, and competency is verified", "The individual''s family gives verbal permission", "The caregiver has prior personal experience giving injections"]'::jsonb, '["El cuidador ha visto un video en línea y se siente seguro", "Una enfermera licenciada de Real Care delega la tarea, se proporciona capacitación y se verifica la competencia", "La familia del individuo da permiso verbal", "El cuidador tiene experiencia personal previa administrando inyecciones"]'::jsonb, 2, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('3a72b37d-46e4-5115-aa9a-b169602d24d2', 1, 'What are the two types of injections covered in this training?', '¿Cuáles son los dos tipos de inyecciones cubiertos en esta capacitación?', '["Intravenous (IV) and Subcutaneous (SubQ)", "Subcutaneous (SubQ) and Intramuscular (IM)", "Intramuscular (IM) and Intravenous (IV)", "Topical and Subcutaneous (SubQ)"]'::jsonb, '["Intravenosa (IV) y Subcutánea (SubQ)", "Subcutánea (SubQ) e Intramuscular (IM)", "Intramuscular (IM) e Intravenosa (IV)", "Tópica y Subcutánea (SubQ)"]'::jsonb, 2, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('3a72b37d-46e4-5115-aa9a-b169602d24d2', 2, 'How many "Rights" of Medication Administration must be verified before every injection?', '¿Cuántos "Derechos" de la Administración de Medicamentos deben verificarse antes de cada inyección?', '["3", "5", "7", "10"]'::jsonb, '["3", "5", "7", "10"]'::jsonb, 3, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('3a72b37d-46e4-5115-aa9a-b169602d24d2', 3, 'Which of the following is a reason to NOT administer an injection?', '¿Cuál de las siguientes es una razón para NO administrar una inyección?', '["The individual is nervous about the injection", "The medication is expired", "It is the individual''s first time receiving an injection", "The injection is scheduled for the afternoon"]'::jsonb, '["El individuo está nervioso por la inyección", "El medicamento está vencido", "Es la primera vez que el individuo recibe una inyección", "La inyección está programada para la tarde"]'::jsonb, 2, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('3a72b37d-46e4-5115-aa9a-b169602d24d2', 4, 'What is the FIRST step in infection control before administering an injection?', '¿Cuál es el PRIMER paso en el control de infecciones antes de administrar una inyección?', '["Put on gloves", "Open the needle packaging", "Wash your hands", "Clean the injection site"]'::jsonb, '["Ponerse los guantes", "Abrir el empaque de la aguja", "Lavarse las manos", "Limpiar el sitio de inyección"]'::jsonb, 3, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('3a72b37d-46e4-5115-aa9a-b169602d24d2', 5, 'After administering an injection, used needles should be:', 'Después de administrar una inyección, las agujas usadas deben:', '["Recapped and placed in regular trash", "Rinsed and returned to the pharmacy", "Disposed of immediately in an approved sharps container", "Placed in a sealed plastic bag"]'::jsonb, '["Taparse de nuevo y colocarse en la basura regular", "Enjuagarse y devolverse a la farmacia", "Desecharse inmediatamente en un contenedor aprobado de objetos punzantes", "Colocarse en una bolsa de plástico sellada"]'::jsonb, 3, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('3a72b37d-46e4-5115-aa9a-b169602d24d2', 6, 'Which of the following is a sign of a SEVERE allergic reaction?', '¿Cuál de los siguientes es un signo de una reacción alérgica SEVERA?', '["Mild soreness at the injection site", "Minor redness", "Swelling of the lips, face, or throat", "A small bruise"]'::jsonb, '["Dolor leve en el sitio de inyección", "Enrojecimiento menor", "Inflamación de los labios, cara o garganta", "Un moretón pequeño"]'::jsonb, 3, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('3a72b37d-46e4-5115-aa9a-b169602d24d2', 7, 'What should you do if you observe signs of a severe allergic reaction?', '¿Qué debe hacer si observa signos de una reacción alérgica severa?', '["Wait to see if symptoms improve on their own", "Stop the procedure, notify the nurse, follow emergency protocol, and call 911 if life-threatening", "Give a second dose of the medication", "Apply ice to the injection site and continue monitoring"]'::jsonb, '["Esperar a ver si los síntomas mejoran por sí solos", "Detener el procedimiento, notificar a la enfermera, seguir el protocolo de emergencia y llamar al 911 si es potencialmente mortal", "Dar una segunda dosis del medicamento", "Aplicar hielo en el sitio de inyección y continuar monitoreando"]'::jsonb, 2, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('3a72b37d-46e4-5115-aa9a-b169602d24d2', 8, 'Which of the following must be documented on the MAR immediately after an injection?', '¿Cuál de los siguientes debe documentarse en el MAR inmediatamente después de una inyección?', '["Only the medication name and date", "Medication name, dose, route, injection site, date, time, and any reactions", "Only whether the individual complained of pain", "The brand name of the syringe used"]'::jsonb, '["Solo el nombre del medicamento y la fecha", "Nombre del medicamento, dosis, ruta, sitio de inyección, fecha, hora y cualquier reacción", "Solo si el individuo se quejó de dolor", "La marca de la jeringa utilizada"]'::jsonb, 2, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('3a72b37d-46e4-5115-aa9a-b169602d24d2', 9, 'How often is injection competency reassessed?', '¿Con qué frecuencia se reevalúa la competencia en inyecciones?', '["Only once, during initial training", "Every 5 years", "Annually, when care plans change, or if incidents occur", "Only if the provider requests it"]'::jsonb, '["Solo una vez, durante la capacitación inicial", "Cada 5 años", "Anualmente, cuando cambian los planes de atención o si ocurren incidentes", "Solo si el proveedor lo solicita"]'::jsonb, 3, '', '');
insert into public.courses (id, slug, title_en, title_es, description_en, description_es, sort, is_specialty, price_cents) values ('0411b7e0-f5df-5815-b67f-52d39f8e885a', 'employee-orientation', 'Employee Orientation', 'Orientación para empleados', 'For Real Care office staff: history, schedules, time off, communication, dress code and client-centered work.', 'Para el personal de oficina de Real Care: historia, horarios, permisos, comunicación, código de vestimenta y trabajo centrado en el cliente.', 18, false, 0);
insert into public.lessons (id, course_id, sort, kind, title_en, title_es, body_en, body_es, video_url, video_seconds, video_source) values ('b08655ae-a58a-529b-a890-b57ec7a164a1', '0411b7e0-f5df-5815-b67f-52d39f8e885a', 0, 'video', 'Watch the training', 'Vea la capacitación', 'Welcome to Real Care! This is your Employee Orientation training. We are glad to have you on the team, and this training will walk you through what you need to know as a new member of the Real Care family.

Real Care, Inc. was founded in 2008. Nicole and her business partner combined their knowledge and experience in service delivery for individuals with developmental and intellectual disabilities, elderly, and at-risk individuals to start this organization. Real Care began with just three clients, and work was done around a dining room table. Since then, the organization has grown to support over one hundred and seventy clients and two hundred caregivers. Real Care is dedicated to helping individuals live their best lives, providing fair compensation to providers and caregivers, and prioritizing well-being through a tailored approach that ensures every person receives the support they need.

As a new hire, you will receive a paperwork packet from our Finance and Benefits Coordinator. This packet includes required employment documents such as your W-4, I-9, direct deposit authorization, and employee policies. Please fill that out promptly and provide copies of your IDs, CPR certification, and any other required documents.

Your standard work schedule is Monday through Friday, eight AM to four PM. You must clock in and out during your shift. If you need to make corrections, use the Alter Clock form. Employees are considered tardy if arriving more than five minutes late. If you anticipate being late or absent, you must notify the Executive Director or the Operations Manager as soon as possible. Schedule flexibility may be approved for medical appointments or other necessary obligations, but missed time must be made up by flexing your schedule within the same workweek. Requests for planned time off must be submitted with at least one week''s notice to the Executive Director.

You will be introduced to our leadership and administrative team. The Executive Director leads the agency, ensures compliance, and oversees program quality and financials. The Operations Manager handles daily operations and supports staff efficiency. The Program Manager oversees service delivery and ensures alignment with client needs and regulations. Our coordinators include the Finance and Benefits Coordinator, Program Coordinator, and Intake and Development Coordinator. Our support staff includes the Documentation Support Coordinator, Program Support Coordinator, Front Desk Support Coordinator, and Administrative Support Staff.

Let me walk you through a few things about the office. Office supplies are located in the cabinet in the Provider File Room — take what you need to get started, and let the Front Desk Support Coordinator know if supplies are running low. The conference room is available for meetings with clients, providers, and staff, so please schedule its use appropriately. Restrooms are located outside of the suite at the end of the hallway on the left.

You may take one paid fifteen-minute break for every four hours worked. An unpaid lunch break of up to one hour may be taken. You are responsible for flexing your schedule to ensure a total of eight hours worked each day. There is a lock box on the outside of the suite, and all locking and security procedures must be followed. Door codes are confidential and should not be shared. All employees are responsible for maintaining a clean workspace and reporting any environmental or equipment issues to the Executive Director.

We all share two main printers — please do not take others'' prints, and return them promptly if you do. Be mindful of HIPAA while in main areas, as visitors may be present or someone may be on a confidential call. Each employee is assigned their own office. You may personalize your workspace as long as it remains professional and non-offensive. No safety hazards like space heaters. Furniture layout may not be changed without approval, and doors should remain open unless you are in a meeting or on the phone.

For office phones, the Front Desk Support Coordinator is primarily responsible for answering incoming calls, and all other staff serve as backup. All calls must be answered courteously. Each office has an assigned extension, and a list of extensions will be provided. For email, all messages must maintain a professional and respectful tone, use approved templates when applicable, and be responded to within two business days.

Regarding the dress code, employees are expected to use good judgment. Acceptable attire includes dress slacks, khakis, blouses, dress shirts, sweaters, and conservative footwear. Leggings are only permitted when worn under a long shirt, tunic, or dress. Jeans without rips or tears are allowed on Fridays and one other day of your choice each week. Unacceptable attire includes sweatpants, shorts, mini-skirts, tank tops with straps under one inch, shirts with offensive language, sweatshirts or hoodies worn alone, and flip-flops or slippers. If attire does not meet standards, you may be asked not to wear the item again, and continued violations may lead to disciplinary action.

Cell phones are allowed for brief personal use — no more than fifteen minutes per day — and should be used during breaks or lunch. Keep your phone on vibrate or off when asked. Games, social media, and recording confidential information are prohibited. Electronic systems and internet access are for work-related purposes only. All company systems and data are the property of Real Care and may be monitored. There is no expectation of privacy on company systems.

Now let''s talk about the people we serve. At Real Care, everything we do is centered around the client. Every decision, interaction, and process should keep their needs, preferences, and goals in mind. Even if you are not directly providing care, your work in an administrative role still impacts clients'' lives. The way you process correspondence, respond to calls, or handle records can affect a client''s day-to-day experience. Our clients have the same rights as anyone else, including the right to privacy, respect, and self-determination. As staff, you should encourage self-advocacy and make sure clients know what they are entitled to.

You will work with several types of providers. Host Home Providers offer twenty-four-hour care in their own homes and can serve up to three clients. Family Caregivers are related individuals providing daily support in the client''s home. Direct Support Professionals and Personal Care Assistants provide comprehensive care in the family home or assist in independent apartments. Supported Community Connection Providers deliver community-based services for clients who do not fit into traditional day program settings. These providers are independent contractors — Family Caregivers and Host Home Providers are ten-ninety-nine non-reportable, while Supported Community Connection and Non-Medical Transportation Providers are ten-ninety-nine taxable.

For file management, provider and client files are maintained in the office and through our cloud storage system, Datto. We also use DocuSign for secure electronic signatures and CamScanner to improve the clarity of unclear documents. File sections cannot be modified — do not move, add, or delete sections. Always maintain organization and confidentiality.

Any changes involving a client or provider are managed through official change forms, which are routed through the office so everyone who needs the information receives it. Many routed documents include router slips where each staff member signs off when they have completed their assigned task.

Our agency values open communication. If you have questions or need guidance, please take advantage of our open-door policy. The more informed and supported you are, the higher the quality of service we can provide. Never hesitate to ask for clarification, resources, or assistance — your questions help everyone succeed.

Thank you for completing the Employee Orientation training. If you have any questions, please contact Real Care staff.', 'Bienvenido a Real Care. Esta es su capacitación de Orientación para Empleados. Nos alegra tenerlo en el equipo, y esta capacitación le guiará a través de lo que necesita saber como nuevo miembro de la familia de Real Care.

Real Care, Inc. fue fundada en el año dos mil ocho. Nicole y su socia combinaron su conocimiento y experiencia en la prestación de servicios para personas con discapacidades del desarrollo e intelectuales, personas de la tercera edad y personas en riesgo para iniciar esta organización. Real Care comenzó con solo tres clientes, y el trabajo se realizaba alrededor de una mesa de comedor. Desde entonces, la organización ha crecido para apoyar a más de ciento setenta clientes y doscientos cuidadores. Real Care se dedica a ayudar a las personas a vivir su mejor vida, proporcionando una compensación justa a los proveedores y cuidadores, y priorizando el bienestar a través de un enfoque personalizado que asegura que cada persona reciba el apoyo que necesita.

Como nuevo empleado, recibirá un paquete de documentación de nuestro Coordinador de Finanzas y Beneficios. Este paquete incluye documentos de empleo requeridos como el W-4, I-9, autorización de depósito directo y políticas del empleado. Por favor complételo lo antes posible y proporcione copias de sus identificaciones, certificación de RCP y cualquier otro documento requerido.

Su horario de trabajo estándar es de lunes a viernes, de ocho de la mañana a cuatro de la tarde. Debe registrar su entrada y salida durante su turno. Si necesita hacer correcciones, use el formulario de Alter Clock. Se considera tardanza si llega más de cinco minutos tarde. Si anticipa llegar tarde o ausentarse, debe notificar al Director Ejecutivo o al Gerente de Operaciones lo antes posible. La flexibilidad de horario puede aprobarse para citas médicas u otras obligaciones necesarias, pero el tiempo perdido debe recuperarse dentro de la misma semana laboral. Las solicitudes de tiempo libre planificado deben enviarse con al menos una semana de anticipación al Director Ejecutivo.

Será presentado a nuestro equipo de liderazgo y administrativo. El Director Ejecutivo dirige la agencia, asegura el cumplimiento y supervisa la calidad del programa y las finanzas. El Gerente de Operaciones maneja las operaciones diarias y apoya la eficiencia del personal. El Gerente de Programas supervisa la prestación de servicios y asegura la alineación con las necesidades del cliente y las regulaciones. Nuestros coordinadores incluyen al Coordinador de Finanzas y Beneficios, Coordinador de Programas y Coordinador de Admisión y Desarrollo. Nuestro personal de apoyo incluye al Coordinador de Apoyo de Documentación, Coordinador de Apoyo de Programas, Coordinador de Apoyo de Recepción y Personal de Apoyo Administrativo.

Permítame explicarle algunas cosas sobre la oficina. Los suministros de oficina se encuentran en el gabinete en la Sala de Archivos de Proveedores — tome lo que necesite para comenzar, y avise al Coordinador de Recepción si los suministros se están agotando. La sala de conferencias está disponible para reuniones con clientes, proveedores y personal, así que por favor programe su uso apropiadamente. Los baños están ubicados fuera de la suite, al final del pasillo a la izquierda.

Puede tomar un descanso pagado de quince minutos por cada cuatro horas trabajadas. Se puede tomar un descanso de almuerzo no pagado de hasta una hora. Es responsable de ajustar su horario para asegurar un total de ocho horas trabajadas cada día. Hay una caja de seguridad en el exterior de la suite, y todos los procedimientos de cierre y seguridad deben seguirse. Los códigos de acceso a la puerta son confidenciales y no deben compartirse. Todos los empleados son responsables de mantener un espacio de trabajo limpio y reportar cualquier problema ambiental o de equipo al Director Ejecutivo.

Todos compartimos dos impresoras principales — por favor no tome las impresiones de otros, y devuélvalas rápidamente si lo hace. Sea consciente de HIPAA mientras esté en áreas principales, ya que pueden haber visitantes presentes o alguien puede estar en una llamada confidencial. A cada empleado se le asigna su propia oficina. Puede personalizar su espacio de trabajo siempre que permanezca profesional y no ofensivo. No se permiten peligros de seguridad como calentadores eléctricos. El arreglo de muebles no puede cambiarse sin aprobación, y las puertas deben permanecer abiertas a menos que esté en una reunión o al teléfono.

Para los teléfonos de la oficina, el Coordinador de Recepción es el principal responsable de contestar las llamadas entrantes, y todo el demás personal sirve como respaldo. Todas las llamadas deben contestarse con cortesía. Cada oficina tiene una extensión asignada y se le proporcionará una lista. Para el correo electrónico, todos los mensajes deben mantener un tono profesional y respetuoso, usar plantillas aprobadas cuando corresponda y responderse dentro de dos días hábiles.

Respecto al código de vestimenta, se espera que los empleados usen buen juicio. La vestimenta aceptable incluye pantalones de vestir, caquis, blusas, camisas de vestir, suéteres y calzado conservador. Los leggings solo se permiten cuando se usan bajo una camisa larga, túnica o vestido. Los jeans sin roturas ni rasgaduras se permiten los viernes y un día adicional de su elección cada semana. La vestimenta inaceptable incluye pantalones deportivos, shorts, minifaldas, camisetas de tirantes con tirantes de menos de una pulgada, camisas con lenguaje ofensivo, sudaderas con capucha usadas solas, y sandalias o pantuflas. Si la vestimenta no cumple con los estándares, se le puede pedir que no use la prenda nuevamente, y las violaciones continuas pueden resultar en acción disciplinaria.

Los teléfonos celulares se permiten para uso personal breve — no más de quince minutos por día — y deben usarse durante los descansos o el almuerzo. Mantenga su teléfono en vibración o apagado cuando se le solicite. Los juegos, redes sociales y grabación de información confidencial están prohibidos. Los sistemas electrónicos y el acceso a internet son para fines laborales solamente. Todos los sistemas y datos de la empresa son propiedad de Real Care y pueden ser monitoreados. No hay expectativa de privacidad en los sistemas de la empresa.

Ahora hablemos de las personas que servimos. En Real Care, todo lo que hacemos está centrado en el cliente. Cada decisión, interacción y proceso debe tener en cuenta sus necesidades, preferencias y metas. Incluso si no está proporcionando atención directamente, su trabajo en un rol administrativo aún impacta la vida de los clientes. La forma en que procesa la correspondencia, responde llamadas o maneja registros puede afectar la experiencia diaria de un cliente. Nuestros clientes tienen los mismos derechos que cualquier otra persona, incluyendo el derecho a la privacidad, el respeto y la autodeterminación. Como personal, debe fomentar la autodefensa y asegurarse de que los clientes sepan cuáles son sus derechos.

Trabajará con varios tipos de proveedores. Los Proveedores de Hogar Anfitrión ofrecen atención las veinticuatro horas en sus propios hogares y pueden atender hasta tres clientes. Los Cuidadores Familiares son personas relacionadas que proporcionan apoyo diario en el hogar del cliente. Los Profesionales de Apoyo Directo y Asistentes de Cuidado Personal proporcionan atención integral en el hogar familiar o asisten en apartamentos independientes. Los Proveedores de Conexión Comunitaria con Apoyo brindan servicios basados en la comunidad para clientes que no se ajustan a los entornos tradicionales de programas diurnos. Estos proveedores son contratistas independientes — los Cuidadores Familiares y Proveedores de Hogar Anfitrión son diez-noventa y nueve no reportables, mientras que los Proveedores de Conexión Comunitaria y Transporte No Médico son diez-noventa y nueve sujetos a impuestos.

Para la gestión de archivos, los archivos de proveedores y clientes se mantienen en la oficina y a través de nuestro sistema de almacenamiento en la nube, Datto. También usamos DocuSign para firmas electrónicas seguras y CamScanner para mejorar la claridad de documentos poco claros. Las secciones de archivos no pueden modificarse — no mueva, agregue ni elimine secciones. Siempre mantenga la organización y la confidencialidad.

Cualquier cambio que involucre a un cliente o proveedor se gestiona a través de formularios oficiales de cambio, que se enrutan a través de la oficina para que todos los que necesitan la información la reciban. Muchos documentos enrutados incluyen hojas de ruta donde cada miembro del personal firma cuando ha completado su tarea asignada.

Nuestra agencia valora la comunicación abierta. Si tiene preguntas o necesita orientación, por favor aproveche nuestra política de puertas abiertas. Cuanto más informado y apoyado esté, mayor será la calidad del servicio que podemos proporcionar. Nunca dude en pedir aclaraciones, recursos o asistencia — sus preguntas ayudan a que todos tengan éxito.

Gracias por completar la capacitación de Orientación para Empleados. Si tiene alguna pregunta, por favor contacte al personal de Real Care.', 'courses/0411b7e0-f5df-5815-b67f-52d39f8e885a/employee-orientation.mp4', 990, 'file');
insert into public.lessons (id, course_id, sort, kind, title_en, title_es, pass_percent) values ('54258fc3-268a-5e79-b9b2-cb3103f6b404', '0411b7e0-f5df-5815-b67f-52d39f8e885a', 1, 'quiz', 'Quiz', 'Prueba', 80);
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('54258fc3-268a-5e79-b9b2-cb3103f6b404', 0, 'What is the standard work schedule for Real Care employees?', '¿Cuál es el horario de trabajo estándar para los empleados de Real Care?', '["Monday–Friday, 9:00 AM – 5:00 PM", "Monday–Friday, 8:00 AM – 4:00 PM", "Monday–Saturday, 8:00 AM – 4:00 PM", "Monday–Friday, 7:00 AM – 3:00 PM"]'::jsonb, '["Lunes a viernes, 9:00 AM – 5:00 PM", "Lunes a viernes, 8:00 AM – 4:00 PM", "Lunes a sábado, 8:00 AM – 4:00 PM", "Lunes a viernes, 7:00 AM – 3:00 PM"]'::jsonb, 2, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('54258fc3-268a-5e79-b9b2-cb3103f6b404', 1, 'How much advance notice is required when requesting planned time off?', '¿Con cuánta anticipación se debe solicitar el tiempo libre planificado?', '["24 hours", "3 days", "1 week", "2 weeks"]'::jsonb, '["24 horas", "3 días", "1 semana", "2 semanas"]'::jsonb, 3, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('54258fc3-268a-5e79-b9b2-cb3103f6b404', 2, 'Within how many business days must employees respond to emails?', '¿Dentro de cuántos días hábiles deben los empleados responder los correos electrónicos?', '["1 business day", "2 business days", "3 business days", "5 business days"]'::jsonb, '["1 día hábil", "2 días hábiles", "3 días hábiles", "5 días hábiles"]'::jsonb, 2, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('54258fc3-268a-5e79-b9b2-cb3103f6b404', 3, 'Which of the following is TRUE about office doors?', '¿Cuál de las siguientes afirmaciones es VERDADERA sobre las puertas de las oficinas?', '["Doors must always remain closed", "Doors should remain open unless you are in a meeting or on the phone", "Doors must always remain open, no exceptions", "Doors should remain closed unless a supervisor is present"]'::jsonb, '["Las puertas siempre deben permanecer cerradas", "Las puertas deben permanecer abiertas a menos que esté en una reunión o al teléfono", "Las puertas siempre deben permanecer abiertas, sin excepciones", "Las puertas deben permanecer cerradas a menos que un supervisor esté presente"]'::jsonb, 2, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('54258fc3-268a-5e79-b9b2-cb3103f6b404', 4, 'On which days are jeans (without rips or tears) permitted?', '¿En qué días se permiten los jeans (sin roturas ni rasgaduras)?', '["Only on Fridays", "Fridays and one other day of the employee''s choice each week", "Any day of the week", "Jeans are never permitted"]'::jsonb, '["Solo los viernes", "Los viernes y un día adicional a elección del empleado cada semana", "Cualquier día de la semana", "Los jeans nunca se permiten"]'::jsonb, 2, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('54258fc3-268a-5e79-b9b2-cb3103f6b404', 5, 'What is the maximum daily personal cell phone use allowed?', '¿Cuál es el máximo de uso personal diario del teléfono celular permitido?', '["5 minutes", "10 minutes", "15 minutes", "30 minutes"]'::jsonb, '["5 minutos", "10 minutos", "15 minutos", "30 minutos"]'::jsonb, 3, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('54258fc3-268a-5e79-b9b2-cb3103f6b404', 6, 'Which cloud storage system does Real Care use for client files?', '¿Qué sistema de almacenamiento en la nube utiliza Real Care para los archivos de clientes?', '["Dropbox", "Google Drive", "Datto", "OneDrive"]'::jsonb, '["Dropbox", "Google Drive", "Datto", "OneDrive"]'::jsonb, 3, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('54258fc3-268a-5e79-b9b2-cb3103f6b404', 7, 'What does a "person-centered approach" mean at Real Care?', '¿Qué significa un "enfoque centrado en la persona" en Real Care?', '["Staff decide what is best for the client without input", "Every decision, interaction, and process should keep the client''s needs, preferences, and goals in mind", "Clients are not involved in their own care planning", "Only clinical staff need to follow person-centered practices"]'::jsonb, '["El personal decide lo que es mejor para el cliente sin consultar", "Cada decisión, interacción y proceso debe tener en cuenta las necesidades, preferencias y metas del cliente", "Los clientes no participan en la planificación de su propia atención", "Solo el personal clínico debe seguir las prácticas centradas en la persona"]'::jsonb, 2, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('54258fc3-268a-5e79-b9b2-cb3103f6b404', 8, 'Which of the following is considered UNACCEPTABLE attire at Real Care?', '¿Cuál de las siguientes es considerada vestimenta INACEPTABLE en Real Care?', '["Dress slacks and a blouse", "Khakis and a golf-style shirt", "Sweatpants and flip-flops", "A casual dress at knee length"]'::jsonb, '["Pantalones de vestir y una blusa", "Caquis y una camisa tipo golf", "Pantalones deportivos y sandalias", "Un vestido casual a la altura de la rodilla"]'::jsonb, 3, '', '');
insert into public.quiz_questions (lesson_id, sort, prompt_en, prompt_es, options_en, options_es, correct, explanation_en, explanation_es) values ('54258fc3-268a-5e79-b9b2-cb3103f6b404', 9, 'Who should an employee notify if they anticipate being tardy or absent?', '¿A quién debe notificar un empleado si anticipa llegar tarde o ausentarse?', '["A coworker", "The Front Desk Support Coordinator", "The Executive Director or Operations Manager", "The Finance and Benefits Coordinator"]'::jsonb, '["A un compañero de trabajo", "Al Coordinador de Apoyo de Recepción", "Al Director Ejecutivo o al Gerente de Operaciones", "Al Coordinador de Finanzas y Beneficios"]'::jsonb, 3, '', '');
