insert into public.form_templates (id, slug, title_en, title_es, schema, per_individual) values ('7d5d4235-a375-52cf-b20f-5968bc526e4c', 'rci-log-notes', 'RCI Log Notes', 'Notas de registro RCI', '{"instructions_en": [{"title": "Before you start", "steps": ["Complete one log note for each visit.", "Write what happened in plain words, as soon as you can after the visit.", "If there was an injury or emergency, also complete an Incident Report."]}], "instructions_es": [{"title": "Antes de empezar", "steps": ["Complete una nota de registro por cada visita.", "Escriba lo que pasó con palabras sencillas, lo antes posible después de la visita.", "Si hubo una lesión o emergencia, también complete un Informe de incidente."]}], "sections": [{"title_en": "Visit", "title_es": "Visita", "fields": [{"id": "individual", "type": "prefill", "source": "individual.full_name", "label_en": "Person supported", "label_es": "Persona apoyada"}, {"id": "visit_date", "type": "date", "label_en": "Date of visit", "label_es": "Fecha de la visita", "required": true}, {"id": "start_time", "type": "time", "label_en": "Start time", "label_es": "Hora de inicio", "required": true}, {"id": "end_time", "type": "time", "label_en": "End time", "label_es": "Hora de término", "required": true}, {"id": "location", "type": "select", "label_en": "Where did support happen?", "label_es": "¿Dónde se brindó el apoyo?", "required": true, "options": [{"value": "home", "en": "Home", "es": "Casa"}, {"value": "community", "en": "Community", "es": "Comunidad"}, {"value": "other", "en": "Other", "es": "Otro"}]}]}, {"title_en": "Notes", "title_es": "Notas", "fields": [{"id": "goals", "type": "prefill", "source": "individual.goals", "label_en": "Current goals", "label_es": "Metas actuales"}, {"id": "activities", "type": "textarea", "label_en": "What did you do together? Include progress on goals.", "label_es": "¿Qué hicieron juntos? Incluya el avance en las metas.", "required": true}, {"id": "mood", "type": "radio", "label_en": "Overall mood", "label_es": "Estado de ánimo general", "required": true, "options": [{"value": "good", "en": "Good", "es": "Bueno"}, {"value": "okay", "en": "Okay", "es": "Regular"}, {"value": "difficult", "en": "Difficult", "es": "Difícil"}]}]}, {"title_en": "Health", "title_es": "Salud", "fields": [{"id": "med_given", "type": "radio", "label_en": "Did you give or help with any medication?", "label_es": "¿Dio o ayudó con algún medicamento?", "required": true, "options": [{"value": "yes", "en": "Yes", "es": "Sí"}, {"value": "no", "en": "No", "es": "No"}]}, {"id": "med_notes", "type": "textarea", "label_en": "Medication, dose and time", "label_es": "Medicamento, dosis y hora", "required": true, "show_if": {"field": "med_given", "equals": "yes"}}, {"id": "concerns", "type": "radio", "label_en": "Any health or safety concerns?", "label_es": "¿Alguna preocupación de salud o seguridad?", "required": true, "options": [{"value": "yes", "en": "Yes", "es": "Sí"}, {"value": "no", "en": "No", "es": "No"}]}, {"id": "concern_details", "type": "textarea", "label_en": "Describe the concern", "label_es": "Describa la preocupación", "required": true, "show_if": {"field": "concerns", "equals": "yes"}}]}, {"title_en": "Sign and submit", "title_es": "Firmar y enviar", "fields": [{"id": "signature", "type": "signature", "label_en": "Type your full name as your signature", "label_es": "Escriba su nombre completo como firma", "required": true}]}]}'::jsonb, true);
insert into public.form_templates (id, slug, title_en, title_es, schema, per_individual) values ('abc1ccdd-9572-5ab7-8c2f-656e5ecefe93', 'fire-drill', 'Fire Disaster Drill', 'Simulacro de incendio y desastre', '{"instructions_en": [{"title": "How to record a drill", "steps": ["Hold a drill every quarter.", "Time the drill from the alarm until everyone is outside or in the safe area.", "If anyone could not leave, explain what support they needed."]}], "instructions_es": [{"title": "Cómo registrar un simulacro", "steps": ["Haga un simulacro cada trimestre.", "Mida el tiempo desde la alarma hasta que todos estén afuera o en el área segura.", "Si alguien no pudo salir, explique qué apoyo necesitó."]}], "sections": [{"title_en": "Drill details", "title_es": "Detalles del simulacro", "fields": [{"id": "drill_date", "type": "date", "label_en": "Date", "label_es": "Fecha", "required": true}, {"id": "drill_time", "type": "time", "label_en": "Time", "label_es": "Hora", "required": true}, {"id": "drill_type", "type": "select", "label_en": "Type of drill", "label_es": "Tipo de simulacro", "required": true, "options": [{"value": "fire", "en": "Fire", "es": "Incendio"}, {"value": "tornado", "en": "Tornado", "es": "Tornado"}, {"value": "other", "en": "Other", "es": "Otro"}]}, {"id": "minutes", "type": "number", "label_en": "Minutes to evacuate", "label_es": "Minutos para evacuar", "required": true}, {"id": "all_out", "type": "radio", "label_en": "Did everyone reach the safe area?", "label_es": "¿Llegaron todos al área segura?", "required": true, "options": [{"value": "yes", "en": "Yes", "es": "Sí"}, {"value": "no", "en": "No", "es": "No"}]}, {"id": "explain", "type": "textarea", "label_en": "Who needed help, and what help?", "label_es": "¿Quién necesitó ayuda y qué tipo de ayuda?", "required": true, "show_if": {"field": "all_out", "equals": "no"}}]}, {"title_en": "Sign and submit", "title_es": "Firmar y enviar", "fields": [{"id": "signature", "type": "signature", "label_en": "Type your full name as your signature", "label_es": "Escriba su nombre completo como firma", "required": true}]}]}'::jsonb, false);
insert into public.form_templates (id, slug, title_en, title_es, schema, per_individual) values ('4ef69307-4ce8-5fcf-ae87-8a580cd0f28a', 'incident-report', 'Incident Report', 'Informe de incidente', '{"instructions_en": [{"title": "Report right away", "steps": ["Call 911 first in any emergency.", "Complete this report the same day.", "Describe only what you saw and did. Do not guess."]}], "instructions_es": [{"title": "Reporte de inmediato", "steps": ["En cualquier emergencia, primero llame al 911.", "Complete este informe el mismo día.", "Describa solo lo que vio e hizo. No adivine."]}], "sections": [{"title_en": "What happened", "title_es": "Qué pasó", "fields": [{"id": "individual", "type": "prefill", "source": "individual.full_name", "label_en": "Person involved", "label_es": "Persona involucrada"}, {"id": "incident_date", "type": "date", "label_en": "Date", "label_es": "Fecha", "required": true}, {"id": "incident_time", "type": "time", "label_en": "Time", "label_es": "Hora", "required": true}, {"id": "incident_type", "type": "select", "label_en": "Type of incident", "label_es": "Tipo de incidente", "required": true, "options": [{"value": "injury", "en": "Injury", "es": "Lesión"}, {"value": "fall", "en": "Fall", "es": "Caída"}, {"value": "medication", "en": "Medication error", "es": "Error de medicamento"}, {"value": "behavior", "en": "Behavioral", "es": "Conductual"}, {"value": "missing", "en": "Missing person", "es": "Persona desaparecida"}, {"value": "other", "en": "Other", "es": "Otro"}]}, {"id": "description", "type": "textarea", "label_en": "Describe what happened", "label_es": "Describa lo que pasó", "required": true}, {"id": "injured", "type": "radio", "label_en": "Was anyone hurt?", "label_es": "¿Alguien resultó herido?", "required": true, "options": [{"value": "yes", "en": "Yes", "es": "Sí"}, {"value": "no", "en": "No", "es": "No"}]}, {"id": "injury_details", "type": "textarea", "label_en": "Describe the injury and care given", "label_es": "Describa la lesión y la atención brindada", "required": true, "show_if": {"field": "injured", "equals": "yes"}}, {"id": "notified", "type": "checkboxes", "label_en": "Who have you notified?", "label_es": "¿A quién le avisó?", "options": [{"value": "guardian", "en": "Guardian", "es": "Tutor"}, {"value": "case_manager", "en": "Case manager", "es": "Administrador de caso"}, {"value": "real_care", "en": "Real Care staff", "es": "Personal de Real Care"}]}]}, {"title_en": "Sign and submit", "title_es": "Firmar y enviar", "fields": [{"id": "signature", "type": "signature", "label_en": "Type your full name as your signature", "label_es": "Escriba su nombre completo como firma", "required": true}]}]}'::jsonb, true);
insert into public.form_templates (id, slug, title_en, title_es, schema, per_individual) values ('ab3686ce-684f-52da-bac7-572efa498329', 'goal-tracking', 'Standard Goal Tracking', 'Seguimiento de metas', '{"instructions_en": [{"title": "Monthly goal check", "steps": ["Complete once a month for each person you support.", "Rate progress on each goal and add examples."]}], "instructions_es": [{"title": "Revisión mensual de metas", "steps": ["Complete una vez al mes por cada persona que apoya.", "Califique el avance en cada meta y agregue ejemplos."]}], "sections": [{"title_en": "Progress", "title_es": "Avance", "fields": [{"id": "individual", "type": "prefill", "source": "individual.full_name", "label_en": "Person supported", "label_es": "Persona apoyada"}, {"id": "goals", "type": "prefill", "source": "individual.goals", "label_en": "Current goals", "label_es": "Metas actuales"}, {"id": "month", "type": "text", "label_en": "Month", "label_es": "Mes", "required": true}, {"id": "progress", "type": "radio", "label_en": "Overall progress this month", "label_es": "Avance general este mes", "required": true, "options": [{"value": "met", "en": "Goals met", "es": "Metas cumplidas"}, {"value": "partial", "en": "Some progress", "es": "Algo de avance"}, {"value": "none", "en": "No progress", "es": "Sin avance"}]}, {"id": "examples", "type": "textarea", "label_en": "Examples", "label_es": "Ejemplos", "required": true}]}, {"title_en": "Sign and submit", "title_es": "Firmar y enviar", "fields": [{"id": "signature", "type": "signature", "label_en": "Type your full name as your signature", "label_es": "Escriba su nombre completo como firma", "required": true}]}]}'::jsonb, true);
