insert into public.messages (provider_id, sender_id, body, created_at) values ('4e6d8d70-2d43-5307-aeeb-664bf5c96898', 'eed26bf3-960d-536c-b609-aa71df39f52c', 'Hi Maria, welcome to the new Real Care portal! Your training, forms and messages are all here now.', '2026-10-20 09:00:00-06');
insert into public.messages (provider_id, sender_id, body, created_at) values ('4e6d8d70-2d43-5307-aeeb-664bf5c96898', '4e6d8d70-2d43-5307-aeeb-664bf5c96898', 'Thanks! Quick question: do I do one fire drill form for the whole house, or one per person?', '2026-10-20 12:14:00-06');
