insert into public.announcements (title_en, title_es, body_en, body_es, audience, created_at) values
('Annual training now renews automatically', 'La capacitación anual ahora se renueva automáticamente',
 'Your required courses will reopen on your own due date each year. Your history stays on your transcript.',
 'Sus cursos requeridos se abrirán de nuevo en su propia fecha límite cada año. Su historial se queda en su certificado de estudios.', '{}', '2026-10-19 08:00:00-06'),
('Host Homes: quarterly fire drills due November 6', 'Hogares anfitriones: simulacros trimestrales para el 6 de noviembre',
 'Please complete your Fire Disaster Drill form in the portal by November 6.',
 'Por favor complete su formulario de simulacro de incendio en el portal antes del 6 de noviembre.', '{host_home}', '2026-10-22 08:00:00-06');
