insert into public.form_templates (id, slug, title_en, title_es, schema, per_individual, version, category, self_start, active, description_en, description_es) values ('8fc0972f-555e-5990-9bf7-7d136f510e09', 'dsp-timesheet', 'DSP/SCC Provider Timesheet', 'Hoja de horas DSP/SCC', '{"instructions_en": [{"title": "How to Complete This Timesheet", "steps": ["This timesheet tracks all direct care services you provide throughout the month. Each row represents one service entry (a visit or shift with a client).", "Use the interactive timesheet grid below to record each service entry. For each row, enter:", "Tips:", "Before submitting:", "⚠️ Important: This timesheet is DUE TO REAL CARE, INC. BY THE 22nd OF EACH MONTH", "DSP Name: Enter your full name as the Direct Support Professional or provider.", "Month of: Enter the month and year you are reporting (e.g., \"December 2025\").", "Date: The date of service (day of month, 1-31)", "Client Initials: The initials of the client you served", "Service Type: Type of service provided (e.g., \"PRS\", \"DSP\", \"SCC\", \"MSP\")", "Time In: When you started service (e.g., \"9:00 AM\")", "Time Out: When you ended service (e.g., \"2:00 PM\")", "Total Hours: This will auto-calculate based on Time In and Time Out", "# of Trips: Number of transportation trips provided (if applicable)"]}], "instructions_es": [{"title": "Cómo llenar este formulario", "steps": ["Conteste cada pregunta.", "Revise sus respuestas.", "Firme y envíe."]}], "sections": [{"title_en": "Details", "title_es": "Details", "fields": [{"id": "f3", "label_en": "DSP Name", "label_es": "DSP Name", "required": true, "help_en": "Your full name as provider", "help_es": "Your full name as provider", "type": "text"}, {"id": "f4", "label_en": "Month of", "label_es": "Month of", "required": true, "help_en": "Enter month and year (e.g., December 2025)", "help_es": "Enter month and year (e.g., December 2025)", "type": "text"}, {"id": "entries", "type": "repeater", "label_en": "Direct care service entries", "label_es": "Servicios de atención directa", "required": true, "help_en": "One row per visit or shift. Hours calculate from Time In and Time Out.", "help_es": "Una fila por visita o turno. Las horas se calculan con la hora de entrada y salida.", "columns": [{"id": "date", "type": "date", "label_en": "Date", "label_es": "Fecha"}, {"id": "initials", "type": "text", "label_en": "Client initials", "label_es": "Iniciales del cliente"}, {"id": "service", "type": "select", "label_en": "Service type", "label_es": "Tipo de servicio", "options": [{"value": "PRS", "en": "PRS", "es": "PRS"}, {"value": "DSP", "en": "DSP", "es": "DSP"}, {"value": "SCC", "en": "SCC", "es": "SCC"}, {"value": "MSP", "en": "MSP", "es": "MSP"}, {"value": "Other", "en": "Other", "es": "Other"}]}, {"id": "in", "type": "time", "label_en": "Time in", "label_es": "Entrada"}, {"id": "out", "type": "time", "label_en": "Time out", "label_es": "Salida"}, {"id": "hours", "type": "hours", "label_en": "Total hours", "label_es": "Horas", "from": ["in", "out"]}, {"id": "trips", "type": "number", "label_en": "# of trips", "label_es": "Viajes"}], "totals": ["hours", "trips"]}]}, {"title_en": "Certification", "title_es": "Certification", "fields": [{"id": "f9", "label_en": "DSP Signature", "label_es": "DSP Signature", "required": true, "help_en": "Enter your name to certify this timesheet", "help_es": "Enter your name to certify this timesheet", "type": "signature"}, {"id": "f10", "label_en": "Date", "label_es": "Date", "required": true, "type": "date"}]}]}'::jsonb, false, 1, 'timesheet', false, false, 'Converted from the intranet Gravity Form (dsp_timesheet_json.json). Draft until Real Care checks it against the original.', 'Convertido del formulario de la intranet. Borrador hasta que Real Care lo revise.');
