insert into public.form_templates (id, slug, title_en, title_es, schema, per_individual, version, category, self_start, active, description_en, description_es) values ('7fc4f30c-d2bf-564d-8a28-50e72251e200', 'medicaid-attendance', 'Medicaid Residential Attendance Record', 'Registro de asistencia residencial de Medicaid', '{"instructions_en": [{"title": "How to Complete This Form", "steps": ["This form tracks residential services and transportation provided each day of the month. Mark the days you provided services using the interactive grids below.", "In the Residential Services Grid, mark each day you provided residential services:", "Only complete this section if you are an approved Non-Medical Transport Provider with Real Care.", "In the Transportation Services Grid, mark each day you provided transportation:", "After marking all days:", "Once all information is complete and accurate:", "Month: Enter the month you are reporting (e.g., January, February).", "Year: Enter the four-digit year (e.g., 2025).", "Provider''s Name: Enter your full name as the service provider.", "Person Receiving Services: Enter the full name of the client receiving services.", "Click on any date (1-31) to mark it with an X indicating service was provided that day.", "You can also use special codes: E (Enrollment), H (Hospital), R (Respite), V (Visit), I (Ineligible), T (Termination), VT (Vacant), J (Jail).", "The grid automatically saves your selections as you work.", "The total number of residential days will be calculated automatically."]}], "instructions_es": [{"title": "Cómo llenar este formulario", "steps": ["Conteste cada pregunta.", "Revise sus respuestas.", "Firme y envíe."]}], "sections": [{"title_en": "Details", "title_es": "Details", "fields": [{"id": "f3", "label_en": "Month", "label_es": "Month", "required": true, "type": "text"}, {"id": "f4", "label_en": "Year", "label_es": "Year", "required": true, "type": "text"}, {"id": "f5", "label_en": "Provider''s Name", "label_es": "Provider''s Name", "required": true, "type": "text"}, {"id": "f6", "type": "prefill", "source": "individual.full_name", "label_en": "Person Receiving Services", "label_es": "Persona"}]}, {"title_en": "Residential Services", "title_es": "Residential Services", "fields": [{"id": "residential_days", "type": "daygrid", "label_en": "Residential services by day", "label_es": "Servicios residenciales por día", "cell": "code", "codes": [{"value": "E", "en": "Enrollment / admission date", "es": "Fecha de inscripción / admisión"}, {"value": "X", "en": "Client in residence", "es": "Cliente en la residencia"}, {"value": "H", "en": "Hospital day / nursing home", "es": "Día de hospital / asilo"}, {"value": "R", "en": "Respite", "es": "Relevo"}, {"value": "V", "en": "Visit to family, friends or special program", "es": "Visita a familia, amigos o programa especial"}, {"value": "I", "en": "Ineligible day", "es": "Día no elegible"}, {"value": "T", "en": "Termination / discharge date", "es": "Fecha de terminación / alta"}, {"value": "VT", "en": "Visit with transportation", "es": "Visita con transporte"}, {"value": "J", "en": "Jail", "es": "Cárcel"}], "rows": [{"id": "res", "en": "Residential", "es": "Residencial"}], "help_en": "Choose X for each day the person was in residence, or one of the special codes.", "help_es": "Elija X para cada día que la persona estuvo en la residencia, o uno de los códigos especiales."}]}, {"title_en": "Transportation Services", "title_es": "Transportation Services", "fields": [{"id": "transport_days", "type": "daygrid", "label_en": "Transportation trips (approved NMT providers only)", "label_es": "Viajes de transporte (solo proveedores NMT aprobados)", "cell": "check", "rows": [{"id": "am", "en": "AM trip", "es": "Viaje de la mañana"}, {"id": "pm", "en": "PM trip", "es": "Viaje de la tarde"}], "help_en": "Maximum 2 trips per day (one there, one back).", "help_es": "Máximo 2 viajes por día (ida y vuelta)."}]}, {"title_en": "Participation Certified", "title_es": "Participation Certified", "fields": [{"id": "f15", "label_en": "Name", "label_es": "Name", "required": true, "type": "text"}, {"id": "f16", "label_en": "Title", "label_es": "Title", "required": true, "type": "text"}, {"id": "f17", "label_en": "Phone No.", "label_es": "Phone No.", "required": true, "type": "phone"}, {"id": "f18", "label_en": "Date", "label_es": "Date", "required": true, "type": "date"}]}]}'::jsonb, true, 1, 'monthly', false, false, 'Converted from the intranet Gravity Form (medicaid_attendance_gf.json). Draft until Real Care checks it against the original.', 'Convertido del formulario de la intranet. Borrador hasta que Real Care lo revise.');
insert into public.form_templates (id, slug, title_en, title_es, schema, per_individual, version, category, self_start, active, description_en, description_es) values ('b010467a-0661-52aa-aa30-139cd445a86e', 'menu-tracking', 'Menu Tracking', 'Registro de menú', '{"instructions_en": [{"title": "How to Complete This Menu Tracking Form", "steps": ["This form documents one week of meals provided to an individual. Complete this form every three months to ensure proper nutritional care and meal variety.", "Use the interactive meal planning grid below to record what was served each day.", "Name: Enter the full name of the individual receiving meals.", "Week Sampled: Enter the date range for the week being documented (e.g., \"12/1/2025 - 12/7/2025\").", "Provider: Enter the name of the meal provider or caregiver."]}, {"title": "For Each Day of the Week", "steps": ["Document meals in all four categories:", "Breakfast: What was served for the morning meal", "Lunch: What was served for the midday meal", "Dinner: What was served for the evening meal", "Snacks: Any snacks provided throughout the day"]}, {"title": "Meal Documentation Requirements", "steps": ["Write down specific foods and beverages served", "Include main dishes, sides, and drinks", "Be descriptive (e.g., \"Scrambled eggs, wheat toast, orange juice\" not just \"Breakfast\")", "List multiple snacks if provided", "Note any meal refusals or substitutions if relevant"]}, {"title": "Nutritional Guidelines", "steps": ["Before submitting, verify:", "⚠️ Important: Documentation must be submitted to Real Care, Inc. no later than the 3rd of the following month. Submit to: documentation@realcarecolorado.com or call 303-284-5818 with questions.", "Meals are to be wholesome and nutritious", "Individuals need to be provided with a choice of meals and snacks", "Ensure variety throughout the week", "Consider dietary restrictions and preferences", "All 7 days are documented (Monday through Sunday)", "All 4 meal categories are filled in for each day", "Meal descriptions are specific and detailed", "Variety is shown across the week", "Nutritious options are included", "Choices are evident in the meal plan", "Review all meal entries for accuracy", "Ensure the week sampled dates are correct"]}], "instructions_es": [{"title": "Cómo llenar este formulario", "steps": ["Conteste cada pregunta.", "Revise sus respuestas.", "Firme y envíe."]}], "sections": [{"title_en": "Details", "title_es": "Details", "fields": [{"id": "f3", "label_en": "Name", "label_es": "Name", "required": true, "help_en": "Full name of individual receiving meals", "help_es": "Full name of individual receiving meals", "type": "text"}, {"id": "f4", "label_en": "Week Sampled", "label_es": "Week Sampled", "required": true, "help_en": "Enter date range (e.g., 12/1/2025 - 12/7/2025)", "help_es": "Enter date range (e.g., 12/1/2025 - 12/7/2025)", "type": "text"}, {"id": "f5", "label_en": "Provider", "label_es": "Provider", "required": true, "help_en": "Name of meal provider or caregiver", "help_es": "Name of meal provider or caregiver", "type": "text"}, {"id": "menu", "type": "repeater", "label_en": "Meals served", "label_es": "Comidas servidas", "required": true, "help_en": "Add a row for each day.", "help_es": "Agregue una fila para cada día.", "columns": [{"id": "date", "type": "date", "label_en": "Date", "label_es": "Fecha"}, {"id": "breakfast", "type": "text", "label_en": "Breakfast", "label_es": "Desayuno"}, {"id": "lunch", "type": "text", "label_en": "Lunch", "label_es": "Almuerzo"}, {"id": "dinner", "type": "text", "label_en": "Dinner", "label_es": "Cena"}, {"id": "snacks", "type": "text", "label_en": "Snacks", "label_es": "Refrigerios"}]}]}]}'::jsonb, true, 1, 'monthly', false, false, 'Converted from the intranet Gravity Form (menu_tracking_json.json). Draft until Real Care checks it against the original.', 'Convertido del formulario de la intranet. Borrador hasta que Real Care lo revise.');
insert into public.form_templates (id, slug, title_en, title_es, schema, per_individual, version, category, self_start, active, description_en, description_es) values ('00144b51-588b-5b0e-8ec8-d3d8a3be8aad', 'nmt-trips', 'NMT Trips Tracking', 'Registro de viajes NMT', '{"instructions_en": [{"title": "How to Complete This Form", "steps": ["This form tracks morning and evening transportation trips provided each day of the month. The form automatically calculates daily totals (maximum 2 per day) and the monthly total.", "For each day of the month, check the boxes that apply:", "Helpful Tip: The table covers dates 1-31 to accommodate all months. For months with fewer days, simply leave the extra dates unchecked.", "Clear All Button: If you need to start over, use the \"Clear All\" button to uncheck all boxes at once.", "Note: Your selections are saved automatically on this device as you work.", "The form automatically calculates totals in two places:", "Client Name: Enter the full name of the client receiving transportation services.", "Month / Year: Select any day in the month you''re reporting. This sets the month and year for all trip entries.", "AM Trip Provided: Check this box if you provided a morning transportation trip on that date.", "PM Trip Provided: Check this box if you provided an evening transportation trip on that date.", "Total Trips Provided (0-2): This column automatically calculates based on your AM and PM selections. The maximum is 2 trips per day."]}, {"title": "Daily Totals", "steps": ["The Total Trips Provided column shows the sum of AM and PM trips for each day (displayed as 0, 1, or 2)."]}, {"title": "Trips by Day Section", "steps": ["This section automatically creates a 31-row summary of all trips. You can add or remove rows using the + and - buttons if needed, though 31 rows are provided by default."]}, {"title": "Monthly Total Trips", "steps": ["At the bottom of the form, the Monthly Total Trips field displays the auto-calculated sum of all trips provided during the month. This value is automatically computed and should be between 0 and 62 trips.", "Important: The total should usually equal AM + PM for each day combined across the month.", "Note: This form stores your entries automatically on your device, so you can return to complete it later if needed.", "Review the daily entries to ensure all transportation trips are accurately recorded.", "Verify that the monthly total makes sense based on the number of days you provided service.", "Confirm that the client name and month/year are correct.", "Click Submit to finalize the form."]}], "instructions_es": [{"title": "Cómo llenar este formulario", "steps": ["Conteste cada pregunta.", "Revise sus respuestas.", "Firme y envíe."]}], "sections": [{"title_en": "Details", "title_es": "Details", "fields": [{"id": "f1", "type": "prefill", "source": "individual.full_name", "label_en": "Client Name", "label_es": "Persona"}, {"id": "f2", "label_en": "Month / Year (pick any day in month)", "label_es": "Month / Year (pick any day in month)", "required": true, "type": "date"}]}, {"title_en": "Transportation Trips", "title_es": "Transportation Trips", "fields": [{"id": "f6", "type": "info", "label_en": "", "label_es": "", "body_en": "Check AM/PM for each day. The daily total auto-calculates (max 2). The monthly total updates below.", "body_es": "Check AM/PM for each day. The daily total auto-calculates (max 2). The monthly total updates below."}, {"id": "trips", "type": "daygrid", "label_en": "Trips by day", "label_es": "Viajes por día", "cell": "check", "required": true, "rows": [{"id": "am", "en": "AM trip provided", "es": "Viaje de la mañana"}, {"id": "pm", "en": "PM trip provided", "es": "Viaje de la tarde"}]}]}]}'::jsonb, true, 1, 'monthly', false, false, 'Converted from the intranet Gravity Form (gravityforms-export-2025-12-04.json). Draft until Real Care checks it against the original.', 'Convertido del formulario de la intranet. Borrador hasta que Real Care lo revise.');
