insert into public.form_templates (id, slug, title_en, title_es, schema, per_individual, version, category, self_start, active, description_en, description_es) values ('d69abc84-5720-5b43-8167-e494ac485101', 'scc-log-notes', 'SCC Log Notes', 'Notas de registro SCC', '{"instructions_en": [{"title": "How to Complete SCC Log Notes", "steps": ["This form documents daily activities provided through Supported Community Connections (SCC) services. Complete one entry for each service session.", "⚠️ Important: Date/Times MUST match the timesheet submitted. Any discrepancy will not be billed/paid to the independent contractor. Please submit your notes and timesheet on the 20th of each month.", "Person Receiving Services Name: Enter the full name of the individual.", "IP Goal: Enter the relevant Individual Plan goal being addressed."]}, {"title": "Basic Information", "steps": ["Date: Date of service", "Start Time: When service began", "End Time: When service ended"]}, {"title": "Activity Documentation", "steps": ["Choices of Activities Offered: List all activity options you presented to the individual", "Specific Location and Activity Selected: Document where you went and what activity the person chose"]}, {"title": "Purpose/Goal (Check all that apply)", "steps": ["Development of Natural Supports in the Community", "Development or introduction to new skill", "Sensory Stimulation (visual, auditory, tactile, etc.)", "Recreation and/or leisure", "Educational/Knowledge Building", "Other (specify)"]}, {"title": "Detailed Explanation", "steps": ["What is the purpose, or the goal of the activity? Check off the opportunities that the activity provided. Use the explanation area to detail:", "The individual''s level of participation", "Their response to the activity", "DO NOT use: \"Good day, bad day, etc.\"", "Be specific and objective in your observations"]}, {"title": "Community Connections", "steps": ["Who did individual connect with in the community? Were prompts needed?", "Describe interactions with community members", "Indicate level of support: Verbal, Physical, or Independent"]}, {"title": "Successes and Support Needs", "steps": ["Discuss Successes and/or areas where additional support may be needed:", "What went well?", "What challenges were encountered?", "What additional support might help?"]}, {"title": "Goal Implementation", "steps": ["Document how the goal was implemented today:", "If you provided a second service session on the same day or a different day, complete Entry #2 with the same level of detail as Entry #1.", "Each entry should document:", "Deadline: Submit notes and timesheet by the 20th of each month.", "How did today''s activity relate to the IP goal?", "What specific actions supported goal progress?", "What outcomes were observed?", "Separate date and times", "Different activities or locations", "Distinct observations and outcomes", "SCC Provider Signature: Enter your name to certify these notes", "Date: Date of completion", "Review all entries for accuracy and completeness", "Verify times match your timesheet"]}], "instructions_es": [{"title": "Cómo llenar este formulario", "steps": ["Conteste cada pregunta.", "Revise sus respuestas.", "Firme y envíe."]}], "sections": [{"title_en": "Details", "title_es": "Details", "fields": [{"id": "f3", "type": "prefill", "source": "individual.full_name", "label_en": "Person Receiving Services Name", "label_es": "Persona"}, {"id": "f4", "label_en": "IP Goal", "label_es": "IP Goal", "required": true, "help_en": "Enter the Individual Plan goal being addressed", "help_es": "Enter the Individual Plan goal being addressed", "type": "textarea"}]}, {"title_en": "Service Entry #1", "title_es": "Service Entry #1", "fields": [{"id": "f6", "label_en": "Date (Entry #1)", "label_es": "Date (Entry #1)", "required": true, "type": "date"}, {"id": "f7", "label_en": "Start Time (Entry #1)", "label_es": "Start Time (Entry #1)", "required": true, "type": "time"}, {"id": "f8", "label_en": "End Time (Ent