insert into public.form_templates (id, slug, title_en, title_es, schema, per_individual, version, category, self_start, active, description_en, description_es) values ('269dc66a-4086-5943-851d-b691633a7604', 'standard-goal-tracking', 'Standard Goal Tracking', 'Seguimiento estándar de metas', '{"instructions_en": [{"title": "How to Complete This Form", "steps": ["This form tracks an individual''s progress on independence goals throughout the month. Complete one form per goal, per month.", "The form is divided into 4 weekly tracking periods. For each period, record:", "Client Name: Enter the full name of the individual whose goal is being tracked.", "Goal: Write the specific independence goal being worked on (e.g., \"Increase independent living skills focused on meal preparation\").", "Effective Date: Enter the date this goal became active.", "Month / Year: Enter the month and year you are tracking (e.g., \"December 2025\")."]}, {"title": "For Each Week", "steps": ["# of times individual worked on the goal: Enter the number of times during that week period. Must be 1 or more times per week.", "# of times provider supported individual: Enter how many times you provided support to help increase their independence related to this goal.", "Type of support provided: Check all that apply: - Verbal - Verbal prompts, encouragement, or instructions", "Supervision - Watching and monitoring the individual", "Physical Assistance - Hands-on help with the task", "Other - Specify any other type of support"]}, {"title": "The Four Weekly Periods", "steps": ["At the end of the tracking period, evaluate whether to continue this goal:", "Days 1-7 (First week)", "Days 8-14 (Second week)", "Days 15-21 (Third week)", "Days 22-31 (Fourth week/end of month)", "Does the individual still express interest? Select Yes or No.", "If No: Describe what new goal the individual wants to work on.", "What would be needed: List resources, training, or support needed to implement the new goal.", "Provider able to assist? Indicate if you can help with the new goal.", "If not able: Explain why you cannot assist with achieving the new goal.", "Additional Comments / Notes: Add any relevant observations, progress notes, barriers encountered, or successes achieved.", "Provider Signature: Enter your name to certify this information.", "Date: Select the date you completed this form.", "Click Submit to finalize the form."]}], "instructions_es": [{"title": "Cómo llenar este formulario", "steps": ["Conteste cada pregunta.", "Revise sus respuestas.", "Firme y envíe."]}], "sections": [{"title_en": "Details", "title_es": "Details", "fields": [{"id": "f3", "type": "prefill", "source": "individual.full_name", "label_en": "Client Name", "label_es": "Persona"}, {"id": "f4", "label_en": "Goal", "label_es": "Goal", "required": true, "help_en": "Describe the specific independence goal (e.g., \"Increase independent living skills focused on meal preparation\")", "help_es": "Describe the specific independence goal (e.g., \"Increase independent living skills focused on meal preparation\")", "type": "textarea"}, {"id": "f5", "label_en": "Effective Date", "label_es": "Effective Date", "required": true, "type": "date"}, {"id": "f6", "label_en": "Month / Year", "label_es": "Month / Year", "required": true, "help_en": "Enter the month and year for this tracking period (e.g., December 2025)", "help_es": "Enter the month and year for this tracking period (e.g., December 2025)", "type": "text"}]}, {"title_en": "Week 1: Days 1st - 7th", "title_es": "Week 1: Days 1st - 7th", "fields": [{"id": "f8", "label_en": "# of times individual worked on the goal", "label_es": "# of times individual worked on the goal", "required": true, "help_en": "Must be 1 or more times per week", "help_es": "Must be 1 or more times per week", "type": "number"}, {"id": "f9", "label_en": "# of times provider supported individual with increasing their independence related to this goal", "label_es": "# of times provider supported