"number"}, {"id": "f25", "label_en": "Type of support provided (Days 22-31)", "label_es": "Type of support provided (Days 22-31)", "required": true, "type": "checkboxes", "options": [{"value": "Verbal", "en": "Verbal", "es": "Verbal"}, {"value": "Supervision", "en": "Supervision", "es": "Supervision"}, {"value": "Physical Assistance", "en": "Physical Assistance", "es": "Physical Assistance"}, {"value": "Other", "en": "Other", "es": "Other"}]}, {"id": "f26", "label_en": "If Other, please specify (Days 22-31)", "label_es": "If Other, please specify (Days 22-31)", "type": "text", "show_if": {"logic": "all", "action": "show", "rules": [{"field": "f25", "op": "is", "value": "Other"}]}}]}, {"title_en": "Goal Assessment", "title_es": "Goal Assessment", "fields": [{"id": "f28", "label_en": "Does the individual still express interest in increasing their independence in this area?", "label_es": "Does the individual still express interest in increasing their independence in this area?", "required": true, "type": "radio", "options": [{"value": "Yes", "en": "Yes", "es": "Yes"}, {"value": "No", "en": "No", "es": "No"}]}, {"id": "f29", "label_en": "If not, what goal does the individual want to work on?", "label_es": "If not, what goal does the individual want to work on?", "type": "textarea", "show_if": {"logic": "all", "action": "show", "rules": [{"field": "f28", "op": "is", "value": "No"}]}}, {"id": "f30", "label_en": "What would be needed to implement the new goal?", "label_es": "What would be needed to implement the new goal?", "type": "textarea", "show_if": {"logic": "all", "action": "show", "rules": [{"field": "f28", "op": "is", "value": "No"}]}}, {"id": "f31", "label_en": "Is the provider able to assist the individual with achieving this goal?", "label_es": "Is the provider able to assist the individual with achieving this goal?", "type": "radio", "options": [{"value": "Yes", "en": "Yes", "es": "Yes"}, {"value": "No", "en": "No", "es": "No"}], "show_if": {"logic": "all", "a